<template>
  <v-dialog v-model="internalDialogVisible" persistent max-width="390" class="top-dialog">
    <v-card>
      <v-card-title>Enter Call Status</v-card-title>

      <v-card-subtitle>Current Phone ID: {{ defaultPhoneStore.defaultPhoneId || 'Not Set' }}</v-card-subtitle>
      <v-card-subtitle>Record Phone ID: {{ phoneId || 'Not Set' }}</v-card-subtitle>
      <v-card-text>
        <textarea v-model="internalInteraction_" placeholder="Interaction" class="e-input bordered-input"
          rows="3"></textarea>
      </v-card-text>
      <v-card-actions class="d-flex justify-space-between">
        <v-container class="pa-0">
          <!-- Group 1: rating change -->
          <v-row>
            <v-col v-for="status in ['dnc', 'wnb']" :key="status" cols="4">
              <v-btn text :class="['bordered-btn', { 'highlighted-btn': internalSelectedStatus === status }]"
                @click="selectStatus(status)">
                {{ statusMapping[status].rating }}:{{ status.toUpperCase() }}
              </v-btn>
            </v-col>
          </v-row>
          <!-- Group 2: Rating 2 -->
          <v-row>
            <v-col v-for="status in ['wp', 'wp1', 'wp2', 'wp3', 'wp4']" :key="status" cols="4">
              <v-btn text :class="['bordered-btn', { 'highlighted-btn': internalSelectedStatus === status }]"
                @click="selectStatus(status)">
                {{ statusMapping[status].rating }}:{{ status.toUpperCase() }}
              </v-btn>
            </v-col>
          </v-row>
          <!-- Group 3: Ratings 4-9 -->
          <v-row>
            <v-col v-for="status in ['fup', 'cv', 'cvt', 'cls', 'wtr', 'wts', 'wtls', 'wtb']" :key="status" cols="4">
              <v-btn text :class="['bordered-btn', { 'highlighted-btn': internalSelectedStatus === status }]"
                @click="selectStatus(status)">
                {{ statusMapping[status].rating }}:{{ status.toUpperCase() }}
              </v-btn>
            </v-col>
          </v-row>
          <!-- Group 4: Rating 10-11 -->
          <v-row>
            <v-col v-for="status in ['ni', 'cft', 'tnt']" :key="status" cols="4">
              <v-btn text :class="['bordered-btn', { 'highlighted-btn': internalSelectedStatus === status }]"
                @click="selectStatus(status)">
                {{ statusMapping[status].rating }}:{{ status.toUpperCase() }}
              </v-btn>
            </v-col>
          </v-row>
          <!-- Group 5: Null ratings -->
          <v-row>
            <v-col v-for="status in ['cbr', 'eg', 'dup','nis', 'nr', 'so','vcm' ]" :key="status" cols="4">
              <v-btn text :class="['bordered-btn', { 'highlighted-btn': internalSelectedStatus === status }]"
                @click="selectStatus(status)">
                {{ statusMapping[status].rating }}: {{ status.toUpperCase() }}
              </v-btn>
            </v-col>
          </v-row>
          <!-- Action Buttons -->
          <v-row>
            <v-col cols="4">
              <v-btn text color="red" class="bordered-btn" @click="closeDialog">Cancel</v-btn>
            </v-col>
            <v-col cols="8">
              <v-btn color="primary" class="bordered-btn confirm-btn" @click="confirmSave"
                :disabled="isConfirmDisabled">Confirm</v-btn>
            </v-col>
          </v-row>
        </v-container>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script setup>
import { ref, watch, computed } from 'vue'
import { PhoneIdStore } from '../stores/user' // Adjust path as needed
import { statusMapping } from '../utils/vgraphql'

// Define props
const props = defineProps({
  showDialog: { type: Boolean, required: true },
  selectedStatus: { type: String, default: '' },
  interaction: { type: String, default: '' },
  rating: { type: Number, default: 0 },
  id: { type: String, default: '' },
  phoneId: { type: String, default: '' }
})

// Define emits
const emit = defineEmits(['update:showDialog', 'update:interaction', 'updateStatus'])

// Reactive variables
const defaultPhoneStore = PhoneIdStore()
const internalDialogVisible = ref(props.showDialog)
const internalSelectedStatus = ref('')
const internalInteraction_ = ref(props.interaction)


// Computed properties
const isConfirmDisabled = computed(() => !internalSelectedStatus.value.trim())

// Methods
const selectStatus = (status) => {
  internalSelectedStatus.value = status
  internalInteraction_.value = statusMapping[status]?.interaction || ""
}

const confirmSave = () => {
  if (!internalSelectedStatus.value) return

  const now = new Date()
  const formattedDateTime = `(${now.getDate()}/${now.getMonth() + 1} ${((now.getHours() % 12) || 12)}${now.getHours() >= 12 ? 'P' : 'A'}) `

  if (internalInteraction_.value && internalInteraction_.value.trim() !== "" && !internalInteraction_.value.endsWith(".")) {
    internalInteraction_.value += "."
  }

  let interactionToEmit = internalInteraction_.value && internalInteraction_.value.trim() !== ""
    ? `${formattedDateTime}${internalInteraction_.value} \n${props.interaction}`.trim()
    : internalInteraction_.value

  const currentPhoneId = defaultPhoneStore.defaultPhoneId || ''
  const recordPhoneId = props.phoneId || ''
  let phoneIdToEmit = currentPhoneId

  if (currentPhoneId !== recordPhoneId && recordPhoneId !== '') {
    const overwriteConfirmed = window.confirm(
      `The Current Phone ID (${currentPhoneId}) differs from the Record Phone ID (${recordPhoneId}). ` +
      `Do you want to overwrite the record with the current Phone ID?`
    )
    if (!overwriteConfirmed) {
      return
    }
  }

  emit('update:interaction', interactionToEmit)
  emit('updateStatus',
    internalSelectedStatus.value + " " + props.selectedStatus,
    interactionToEmit,
    statusMapping[internalSelectedStatus.value]?.rating ?? props.rating,
    props.id,
    phoneIdToEmit
  )

  closeDialog()
}

const closeDialog = () => {
  internalDialogVisible.value = false
  emit('update:showDialog', internalDialogVisible.value)
}

// Watchers
watch(() => props.showDialog, (newVal) => {
  internalDialogVisible.value = newVal
  if (newVal) {
    internalSelectedStatus.value = props.selectedStatus
    internalInteraction_.value = props.interaction
  }
})

watch(() => props.interaction, (newVal) => {
  internalInteraction_.value = newVal
})

watch(() => props.selectedStatus, (newVal) => {
  internalSelectedStatus.value = newVal
})
</script>

<style scoped>
.bordered-input {
  border: 1px solid #ccc;
  border-radius: 5px;
  padding: 8px;
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  font-family: inherit;
  font-size: inherit;
}

.bordered-input:hover,
.bordered-input:focus {
  border-color: #1976d2;
  outline: none;
  box-shadow: 0 0 4px #1976d2;
}

.bordered-btn {
  border: 1px solid #ccc !important;
  border-radius: 5px;
  padding: 8px;
  background-color: transparent;
  width: 100%;
  margin: 2px 0;
}

.bordered-btn:hover {
  border-color: #1976d2 !important;
}

.highlighted-btn {
  background-color: #1976d2;
  color: white;
}

.confirm-btn {
  width: 100%;
  margin-top: 8px;
}

.top-dialog {
  margin-top: 0 !important;
}

.top-dialog .v-dialog {
  margin-top: 0 !important;
  position: fixed !important;
  top: 160px !important;
}
</style>