<template>
  <div class="todo-list">
    <h2>Todo List</h2>

    <v-form @submit.prevent="handleCreateTodo" class="mb-4">
      <v-row>
        <v-col cols="12" sm="6">
          <v-text-field v-model="newTodo" label="Add a new todo" :disabled="loading" outlined dense></v-text-field>
        </v-col>
        <v-col cols="6" sm="3">
          <v-select v-model="priority" :items="[1, 2, 3, 4, 5]" label="Priority" :disabled="loading" outlined dense></v-select>
        </v-col>
        <v-col cols="6" sm="3">
          <v-menu v-model="startDateMenu" :close-on-content-click="false">
            <template v-slot:activator="{ props: activatorProps }">
              <v-text-field v-model="startDateFormatted" label="Start Date" prepend-icon="mdi-calendar" readonly
                v-bind="activatorProps" :disabled="loading" outlined dense></v-text-field>
            </template>
            <v-date-picker v-model="startDate" @update:modelValue="startDateMenu = false" />
          </v-menu>
        </v-col>
        <v-col cols="6" sm="3">
          <v-menu v-model="startTimeMenu" :close-on-content-click="false">
            <template v-slot:activator="{ props: activatorProps }">
              <v-text-field v-model="startTime" label="Start Time" prepend-icon="mdi-clock-outline" readonly
                v-bind="activatorProps" :disabled="loading" outlined dense></v-text-field>
            </template>
            <v-time-picker v-model="startTime" format="24hr" @update:modelValue="startTimeMenu = false" />
          </v-menu>
        </v-col>
        <v-col cols="6" sm="3">
          <v-menu v-model="dateMenu" :close-on-content-click="false">
            <template v-slot:activator="{ props: activatorProps }">
              <v-text-field v-model="dueDateFormatted" label="Due Date" prepend-icon="mdi-calendar" readonly
                v-bind="activatorProps" :disabled="loading" outlined dense></v-text-field>
            </template>
            <v-date-picker v-model="dueDate" @update:modelValue="dateMenu = false" />
          </v-menu>
        </v-col>
        <v-col cols="6" sm="3">
          <v-menu v-model="timeMenu" :close-on-content-click="false">
            <template v-slot:activator="{ props: activatorProps }">
              <v-text-field v-model="dueTime" label="Due Time" prepend-icon="mdi-clock-outline" readonly
                v-bind="activatorProps" :disabled="loading" outlined dense></v-text-field>
            </template>
            <v-time-picker v-model="dueTime" format="24hr" @update:modelValue="timeMenu = false" />
          </v-menu>
        </v-col>
        <v-col cols="6" sm="3">
          <v-btn type="submit" color="primary" :disabled="loading" depressed>
            Add
          </v-btn>
        </v-col>
      </v-row>
    </v-form>

    <v-btn color="error" @click="handleDeleteMarked" :disabled="loading || !todos.some(todo => todo.markedForDelete)"
      class="mb-4" depressed>
      Delete Marked Todos
    </v-btn>

    <!-- Filter Controls -->
    <v-row class="mb-4">
      <v-col cols="6" sm="3">
        <v-select v-model="filterCategory" :items="filterCategoryOptions" label="Filter by Category" outlined dense
          clearable @update:modelValue="applyFilters"></v-select>
      </v-col>
      <v-col cols="6" sm="3">
        <v-select v-model="filterAssignedTo" :items="userOptions" label="Filter by Assigned To" outlined dense
          clearable @update:modelValue="applyFilters"></v-select>
      </v-col>
    </v-row>

    <v-progress-linear v-if="loading" indeterminate color="primary"></v-progress-linear>

    <v-data-table v-else :headers="headers" :items="filteredTodos" :items-per-page="-1" class="elevation-1" :footer-props="{
      'items-per-page-options': [5, 10, 20, -1],
      'items-per-page-text': 'Todos per page:'
    }">
      <template v-slot:item.done="{ item }">
        <v-checkbox v-model="item.done" @change="handleToggleTodo(item.id, item.done)" hide-details dense></v-checkbox>
      </template>
      <template v-slot:item.markedForDelete="{ item }">
        <v-checkbox v-model="item.markedForDelete" @change="handleMarkForDelete(item.id, item.markedForDelete)"
          hide-details dense></v-checkbox>
      </template>
      <template v-slot:item.name="{ item }">
        <span :class="{
          'text-decoration-line-through text-grey': item.done,
          'text-red': item.markedForDelete
        }">
          {{ item.name }}
        </span>
      </template>
      <template v-slot:item.startDate="{ item }">
        {{ formatDisplayDate(item.startDate) || 'N/A' }}
      </template>
      <template v-slot:item.dueDate="{ item }">
        {{ formatDisplayDate(item.dueDate) || 'N/A' }}
      </template>
      <template v-slot:item.category="{ item }">
        {{ item.category || 'None' }}
      </template>
      <template v-slot:item.assignedTo="{ item }">
        {{ item.assignedTo || 'All' }}
      </template>
      <template v-slot:item.actions="{ item }">
        <v-icon small class="mr-2" @click="openEditDialog(item)">
          mdi-pencil
        </v-icon>
      </template>
    </v-data-table>
  </div>

  <TodoEditDialog v-model="editDialog" :todo="editedTodo" :category-options="categoryOptions"
    :user-options="userOptions" :loading="loading" @save="handleSaveEdit" @cancel="handleCancelEdit" />
</template>

<script>
import TodoEditDialog from './TodoEditDialog.vue';
import { VTimePicker } from 'vuetify/labs/VTimePicker';
import { ref, onMounted, computed, watch } from 'vue';
import {
  fetchTodos,
  createTodo,
  updateTodo,
  deleteTodo
} from '../utils/todoService';

export default {
  name: 'TodoList',
  components: {
    VTimePicker,
    TodoEditDialog
  },
  setup() {
    const todos = ref([]);
    const newTodo = ref('');
    const priority = ref(1);
    const startDate = ref(null);
    const dueDate = ref(null);
    const dueTime = ref('12:00');
    const startDateMenu = ref(false);
    const dateMenu = ref(false);
    const timeMenu = ref(false);
    const loading = ref(false);
    const startTime = ref('00:00');
    const startTimeMenu = ref(false);

    const categoryOptions = [
      'Personal', 'Work', 'Home', 'Shopping', 'Health', 'Education',
      'Projects', 'Finance', 'Calls', 'Events', 'Ideas', 'CheckList'
    ];
    const userOptions = ['All', 'Alyssa', 'Ashton', 'Alvin'];

    // Filter variables with localStorage persistence
    const filterCategory = ref(localStorage.getItem('filterCategory') || null);
    const filterAssignedTo = ref(localStorage.getItem('filterAssignedTo') || null);
    const filterCategoryOptions = computed(() => ['All', ...categoryOptions]);

    // Watch filter changes and save to localStorage
    watch(filterCategory, (newValue) => {
      if (newValue === null) {
        localStorage.removeItem('filterCategory');
      } else {
        localStorage.setItem('filterCategory', newValue);
      }
    });

    watch(filterAssignedTo, (newValue) => {
      if (newValue === null) {
        localStorage.removeItem('filterAssignedTo');
      } else {
        localStorage.setItem('filterAssignedTo', newValue);
      }
    });

    const headers = ref([
      { title: 'Done', value: 'done', sortable: true },
      { title: 'Name', value: 'name', sortable: true },
      { title: 'Priority', value: 'priority', sortable: true },
      { title: 'Assigned To', value: 'assignedTo', sortable: true },
      { title: 'Start Date', value: 'startDate', sortable: true },
      { title: 'Due Date', value: 'dueDate', sortable: true },
      { title: 'Category', value: 'category', sortable: true },
      { title: 'Actions', value: 'actions', sortable: false },
      { title: 'Mark for Delete', value: 'markedForDelete', sortable: true }
    ]);

    const editDialog = ref(false);
    const editedTodo = ref({});

    // Computed property for filtered todos
    const filteredTodos = computed(() => {
      let filtered = [...todos.value];
      if (filterCategory.value && filterCategory.value !== 'All') {
        filtered = filtered.filter(todo => todo.category === filterCategory.value);
      }
      if (filterAssignedTo.value && filterAssignedTo.value !== 'All') {
        filtered = filtered.filter(todo => todo.assignedTo === filterAssignedTo.value);
      }
      return filtered;
    });

    const applyFilters = () => {
      // No need for logic here since filteredTodos recomputes automatically
    };

    const openEditDialog = (item) => {
      editedTodo.value = { ...item };
      editDialog.value = true;
    };

    const handleSaveEdit = async (updatedTodo) => {
      try {
        loading.value = true;
        const result = await updateTodo(updatedTodo.id, {
          name: updatedTodo.name,
          description: updatedTodo.description,
          priority: updatedTodo.priority,
          startDate: updatedTodo.startDate,
          dueDate: updatedTodo.dueDate,
          category: updatedTodo.category,
          assignedTo: updatedTodo.assignedTo
        });

        const index = todos.value.findIndex(t => t.id === result.id);
        if (index !== -1) {
          todos.value.splice(index, 1, result);
        }
      } catch (error) {
        console.error('Error updating todo:', error);
      } finally {
        loading.value = false;
        editDialog.value = false;
      }
    };

    const handleCancelEdit = () => {
      editDialog.value = false;
    };

    const formatDateTime = (dateString) => {
      if (!dateString) return null;
      const date = new Date(dateString);
      return date.toLocaleDateString('en-GB');
    };

    const startDateFormatted = computed(() => formatDateTime(startDate.value));
    const dueDateFormatted = computed(() => formatDateTime(dueDate.value));

    const formatDisplayDate = (dateString) => {
      if (!dateString) return null;
      try {
        const date = new Date(dateString);
        return date.toLocaleString('en-GB', {
          day: '2-digit',
          month: '2-digit',
          year: '2-digit',
          hour: '2-digit',
          minute: '2-digit'
        });
      } catch {
        return null;
      }
    };

    const loadTodos = async () => {
      loading.value = true;
      try {
        const todoData = await fetchTodos();
        todos.value = todoData;
      } catch (error) {
        console.error('Failed to load todos:', error);
      }
      loading.value = false;
    };

    const handleCreateTodo = async () => {
      if (!newTodo.value.trim()) return;

      try {
        loading.value = true;
        let fullStartDate = null;
        let fullDueDate = null;

        if (startDate.value && startTime.value) {
          let startDateStr = startDate.value;
          if (startDateStr instanceof Date) {
            startDateStr = [
              startDateStr.getFullYear(),
              String(startDateStr.getMonth() + 1).padStart(2, '0'),
              String(startDateStr.getDate()).padStart(2, '0')
            ].join('-');
          }
          if (/^\d{4}-\d{2}-\d{2}$/.test(startDateStr)) {
            const [year, month, day] = startDateStr.split('-');
            const [hours, minutes] = startTime.value.split(':');
            fullStartDate = new Date(
              parseInt(year),
              parseInt(month) - 1,
              parseInt(day),
              parseInt(hours),
              parseInt(minutes)
            ).toISOString();
          }
        }

        if (dueDate.value && dueTime.value) {
          let dueDateStr = dueDate.value;
          if (dueDateStr instanceof Date) {
            dueDateStr = [
              dueDateStr.getFullYear(),
              String(dueDateStr.getMonth() + 1).padStart(2, '0'),
              String(dueDateStr.getDate()).padStart(2, '0')
            ].join('-');
          }
          if (/^\d{4}-\d{2}-\d{2}$/.test(dueDateStr)) {
            const [year, month, day] = dueDateStr.split('-');
            const [hours, minutes] = dueTime.value.split(':');
            fullDueDate = new Date(
              parseInt(year),
              parseInt(month) - 1,
              parseInt(day),
              parseInt(hours),
              parseInt(minutes)
            ).toISOString();
          }
        }

        console.log('Final dates:', { start: fullStartDate, due: fullDueDate });

        const todoPayload = {
          name: newTodo.value.trim(),
          priority: priority.value,
          startDate: fullStartDate,
          dueDate: fullDueDate,
          category: filterCategory.value !== 'All' ? filterCategory.value : null,
          assignedTo: filterAssignedTo.value !== 'All' ? filterAssignedTo.value : null
        };

        const createdTodo = await createTodo(todoPayload);
        todos.value.push(createdTodo);

        newTodo.value = '';
        priority.value = 1;
        startDate.value = null;
        dueDate.value = null;
        startTime.value = '00:00';
        dueTime.value = '12:00';
      } catch (error) {
        console.error('Create failed:', error);
        alert(`Error: ${error.message}`);
      } finally {
        loading.value = false;
      }
    };

    const handleToggleTodo = async (id, newValue) => {
      try {
        const updatedTodo = await updateTodo(String(id), { done: newValue });
        const index = todos.value.findIndex(todo => todo.id === id);
        if (index !== -1) {
          todos.value.splice(index, 1, updatedTodo);
        }
      } catch (error) {
        console.error('Failed to update todo:', error);
      }
    };

    const handleMarkForDelete = async (id, newValue) => {
      try {
        const updatedTodo = await updateTodo(String(id), { markedForDelete: newValue });
        const index = todos.value.findIndex(todo => todo.id === id);
        if (index !== -1) {
          todos.value.splice(index, 1, updatedTodo);
        }
      } catch (error) {
        console.error('Failed to mark todo for deletion:', error);
      }
    };

    const handleDeleteMarked = async () => {
      loading.value = true;
      try {
        const markedTodos = todos.value.filter(todo => todo.markedForDelete);
        for (const todo of markedTodos) {
          await deleteTodo(todo.id);
        }
        todos.value = todos.value.filter(todo => !todo.markedForDelete);
      } catch (error) {
        console.error('Failed to delete marked todos:', error);
      }
      loading.value = false;
    };

    onMounted(() => {
      loadTodos();
    });

    return {
      todos,
      newTodo,
      priority,
      startDate,
      dueDate,
      dueTime,
      startDateFormatted,
      dueDateFormatted,
      startDateMenu,
      dateMenu,
      timeMenu,
      categoryOptions,
      loading,
      headers,
      userOptions,
      handleCreateTodo,
      handleToggleTodo,
      handleMarkForDelete,
      handleDeleteMarked,
      formatDisplayDate,
      handleCancelEdit,
      openEditDialog,
      TodoEditDialog,
      editDialog,
      editedTodo,
      handleSaveEdit,
      startTime,
      startTimeMenu,
      filterCategory,
      filterAssignedTo,
      filterCategoryOptions,
      filteredTodos,
      applyFilters
    };
  }
};
</script>

<style scoped>
.todo-list {
  max-width: 1000px;
  margin: 0 auto;
  padding: 20px;
}

.mb-4 {
  margin-bottom: 16px;
}

.text-decoration-line-through {
  text-decoration: line-through;
}

.text-grey {
  color: #888;
}

.text-red {
  color: #ff4444;
}

.v-data-table {
  margin-top: 20px;
}

/* Enforce column widths */
.v-data-table >>> th:nth-child(1) { /* Done */
  width: 40px !important;
  min-width: 40px !important;
  max-width: 40px !important;
  padding: 0 4px !important;
}

.v-data-table >>> td:nth-child(1) { /* Done cells */
  width: 60px !important;
  min-width: 60px !important;
  max-width: 60px !important;
  padding: 0 8px !important;
}

.v-data-table >>> th:nth-child(3) { /* Priority */
  width: 50px !important;
  min-width: 50px !important;
  max-width: 50px !important;
  padding: 0 8px !important;
}

.v-data-table >>> td:nth-child(3) { /* Priority cells */
  width: 50px !important;
  min-width: 50px !important;
  max-width: 50px !important;
  padding: 0 8px !important;
}

.v-data-table >>> th:nth-child(10) { /* Mark for Delete */
  width: 80px !important;
  min-width: 80px !important;
  max-width: 80px !important;
  padding: 0 8px !important;
}

.v-data-table >>> td:nth-child(10) { /* Mark for Delete cells */
  width: 80px !important;
  min-width: 80px !important;
  max-width: 80px !important;
  padding: 0 8px !important;
}

/* Center-align narrow columns */
.v-data-table >>> th,
.v-data-table >>> td {
  text-align: center !important;
}
</style>