<template>
  <div class="custom-form-container">
    <div v-if="!showStatusDialog && contact">
      <v-btn @click="saveContact" color="primary" class="mx-1" rounded
        style="width: 20%; min-width: 20px; height: 70px;">Save</v-btn>

      <v-btn rounded @click="showStatusDialog = true"
        :disabled="!contacts || !Array.isArray(contacts) || indexIndex === contacts.length - 1" color="#00AA55"
        class="mx-1" style="width: 20%; min-width: 20px; height: 70px;">
        Save <v-icon>mdi-arrow-right</v-icon>
      </v-btn>
      <v-btn rounded @click="cancelEdit" color="blue" style="width: 20%; min-width: 20px; height: 70px;">Cancel</v-btn>
      <v-btn rounded @click="deleteContact" color="red" class="mx-1" style="width: 20%; min-width: 20px; height: 70px;">
        <v-icon>mdi-delete</v-icon> Delete
      </v-btn>
      <v-select v-model="selectedLanguage" :items="languageOptions" label="Select Language" outlined dense
        item-text="title" item-value="value" style="width: 25%; min-width: 120px; margin-right: 10px;"
        class="mx-1"></v-select>
      <v-btn @click="viewFirstNote(selectedLanguage)" color="green" class="mx-1" rounded
        style="width: 15%; min-width: 120px; height: 70px;">
        <v-icon>mdi-note-text</v-icon> View Note
      </v-btn>
      <v-btn rounded @click="makeCall2(editContactData, props.index, props.contacts)" :color="primary"
        style="width: 20%; min-width: 50px; height: 70px;" class="mx-1">
        <v-icon>mdi-monitor-cellphone-star</v-icon>
      </v-btn>
      <v-btn :disabled="isPhoneDisabled(editContactData)" rounded :href="`tel:${editContactData.phoneNumber}`"
        color="primary" @click="handleCallClick" style="width: 20%; min-width: 50px; height: 70px;" class="mx-1">
        # <v-icon>mdi-phone-in-talk</v-icon>
      </v-btn>
      <v-btn rounded @click="rowSendWhatsApp(editContactData)" color="primary"
        style="width: 20%; min-width: 50px; height: 70px;" class="mx-1" :disabled="isLoading || fetchError">
        <v-icon>mdi-whatsapp</v-icon>
        <template v-if="isLoading">
          <v-progress-circular indeterminate size="24"></v-progress-circular>
        </template>
        <span v-if="fetchError" class="error--text">Error</span>
      </v-btn>
    </div>

    <div v-if="showStatusDialog">
      <br />
    </div>

    <v-form v-if="contact" ref="contactForm" style="max-width: 1800px; margin: 0 auto;">
      <h4><u>{{ contact.id }}</u> #️⃣ <u>{{ contact.no }}</u> 👦🏻 <u>{{ contact.name }}</u> ☎ <u>{{ contact.phoneNumber
          }}</u></h4>
      <h4>🏢 <u>{{ contact.project }}</u> 📲 {{ editContactData.doc }} 📞 {{ editContactData.called }} Contacted (0/1):
        {{
          editContactData.contacted }}</h4>
      <h4>🙌<u>{{ editContactData.interaction }}</u></h4>
      <v-select v-model="editContactData.language" :items="languageOptions" label="Language" outlined dense></v-select>
      <v-row dense class="my-0">
        <v-col md="4">
          <v-select v-model="editContactData.phoneId" :items="phoneIdOptions" label="PhoneId" outlined></v-select>
        </v-col>
        <v-col md="4">
          <v-select v-model="editContactData.requestType" :items="requestTypes" label="Request Type"
            outlined></v-select>
        </v-col>

        <v-col md="4">
          <v-select v-model="editContactData.stage" :items="stageOptions" label="Stage" outlined></v-select>
        </v-col>
      </v-row>
      <InfoSection v-model:info="editContactData.info" :tenant-profiles="tenantProfiles" />
      <v-row dense class="my-0">
        <v-col md="4">
          <v-text-field label="Status" v-model="editContactData.status" class="edit-mode"></v-text-field>
        </v-col>
        <v-col md="4">
          <v-text-field label="Address" v-model="editContactData.address" class="edit-mode"></v-text-field>
        </v-col>
        <v-col md="4">
          <v-text-field label="advUrl Date" v-model="editContactData.advUrlDate" type="date"
            class="edit-mode"></v-text-field>
        </v-col>
      </v-row>
      <v-row dense class="my-0">
        <v-col md="3">
          <v-text-field label="advUrl" v-model="editContactData.advUrl" class="edit-mode"></v-text-field>
        </v-col>
        <v-col md="3">
          <v-text-field label="NotionURL" v-model="editContactData.notionUrl" class="edit-mode"></v-text-field>
        </v-col>
        <v-col md="3">
          <v-select v-model="editContactData.rating" :items="ratingOptions" item-title="text"
            item-value="value"></v-select>
        </v-col>
        <v-col md="3">
          <v-text-field label="Called" v-model.number="editContactData.called" type="number"
            class="edit-mode"></v-text-field>
        </v-col>
      </v-row>
      <v-row dense class="my-0">
        <v-col md="4">
          <v-text-field label="facebookUrl" v-model="editContactData.facebookUrl" class="edit-mode"></v-text-field>
        </v-col>
        <v-col md="4">
          <h2>Last Call Date: {{ convertYMD2DMY(editContactData.lastCall) }}</h2>
        </v-col>
        <v-col md="4">
          <h2>Next Call Date: {{ convertYMD2DMY(editContactData.nextCall) }}</h2>
        </v-col>
      </v-row>
      <v-menu v-model="isMenuActive" transition="scale-transition" max-height="100px">
        <v-select v-if="item" v-model="item.language" :items="languageOptions" label="Language" outlined
          dense></v-select>
        <template #activator="{ on, attrs }">
          <v-textarea v-model="editContactData.interaction" label="Interaction" outlined v-bind="attrs" v-on="on"
            @keydown="handleKeydown" />
        </template>
        <v-list>
          <v-list-item v-for="(option, index) in filteredOptions" :key="index" @click="selectOption(option)">
            <v-list-item-title>{{ option }}</v-list-item-title>
          </v-list-item>
        </v-list>
      </v-menu>
      <v-snackbar v-model="snackbar.show" :timeout="3000" color="success" top>
        {{ snackbar.message }}
      </v-snackbar>
      <h2>task:</h2>
      <EnhancedEditor :key="editContactData.task" ref="editorRef" :initialData="editContactData.task" />
      <div>
        <statusDialog v-model:showDialog="showStatusDialog" :selectedStatus="editContactData.status"
          :interaction="editContactData.interaction" :rating="editContactData.rating" :id="editContactData.id"
          :phoneId="editContactData.phoneId || ''" @updateStatus="handleStatusUpdate" />
      </div>
      <div>
        <h3>Call Log</h3>
        <ul>
          <li v-for="(log, index) in callLog" :key="index">
            {{ log.name }} - {{ log.phoneNumber }} - {{ log.time }}
          </li>
        </ul>
      </div>
    </v-form>
    <note-editor-dialog :open="isViewDialogOpen" @save="handleSave" :is-editing="true" :note="editingNote"
      @close="isViewDialogOpen = false" />
    <span v-if="fetchError" class="error--text">Load Failed</span>
  </div>
</template>

<script setup>
import { useMutation } from '@vue/apollo-composable'
import { ref, watch, onMounted, getCurrentInstance } from 'vue'
import { getDeviceInfo, convertYMD2DMY, convertDMY2YMDtime, convertDMY2YMD, isPhoneDisabled, isPhoneDisabled2, UPDATE_CALLME } from '../utils/contactUtils.js'
import statusDialog from './statusDialog.vue'
import EnhancedEditor from './EnhancedEditor.vue'
import { useUserStore } from '@/stores/user'
import { getTodayDate } from '../utils/contactUtils'
import { statusMapping, tenantProfiles, updateNoteMutation, fetchMessageTemplates } from '../utils/vgraphql'
import NoteEditorDialog from './NoteEditorDialog.vue'
import { fetchNotes } from '../utils/todoService.js'
import client from '../apollo-client'
import InfoSection from './InfoSection.vue'

// Define props with correct types
const props = defineProps({
  contact: Object,
  onSave: Function,
  onDelete: Function,
  onCancel: Function,
  index: Number,
  selectedUser: String,
  selectedPhoneId: String,
  contacts: Array, // Changed to Array to match original intent
  nextContact: Function,
})

// Reactive variables
const isEditing = ref(true)
const isViewDialogOpen = ref(false)
const editingNote = ref(null)
const messageOptions = ref([])
const fetchError = ref(false)
const internalContact = ref({ ...props.contact })
const { appContext } = getCurrentInstance()
const cleanPhoneNumber = appContext.config.globalProperties.cleanPhoneNumber
const snackbar = ref({ show: false, message: "Record has been saved successfully!" })
const loading = ref(false)
const isLoading = ref(false)
const editorRef = ref(null)
const showStatusDialog = ref(false)
const process = ref('')
const status = ref('')
const _interaction = ref('')
const stage = ref('')
const task = ref('')
const delegate = ref('')
const isMenuActive = ref(false)
const filteredOptions = ref([])
const userStore = useUserStore()
const selectedLanguage = ref('en')
const languageOptions = ref([
  { title: 'English', value: 'en' },
  { title: 'Chinese', value: 'cn' },
  { title: 'Cantonese', value: 'ct' },
  { title: 'BM', value: 'bm' },
])



const ratingOptions = ref([])
const computeRatingOptions = () => {
  const options = Object.entries(statusMapping)
    .filter(([_, data]) => data.rating !== null)
    .map(([status, data]) => ({
      text: `${data.rating}: ${status.toUpperCase()}`,
      value: data.rating
    }))
  ratingOptions.value = options
}

computeRatingOptions()

const callLog = ref([])
const editContactData = ref({
  interaction: '',
  doc: '',
  status: '',
  _interaction: '',
  language: 'en',
  rating: 0,
  called: 0,
  contacted: 0,
  requestType: '',
  address: '',
  advUrl: '',
  advUrlDate: '',
  process: '',
  stage: '',
  task: '',
  delegate: '',
  phoneId: '',
  facebookUrl: '',
  notionUrl: '',
})

const requestTypes = ["buyer", "project_buyer", "project_seller", "seller", "lease", "rent"]
const phoneIdOptions = ['Alyssa H', 'Ashton H', 'Alvin S', '']
const stageOptions = ref(['Qualify', 'Follow-up', 'Close']) // Added to fix stage v-select

// Methods
const applyTemplate = (event) => {
  const selectedIndex = event.target.value
  if (selectedIndex !== "") {
    editContactData.value.info = tenantProfiles[selectedIndex][2]
    event.target.value = ""
  }
}

const getGreeting = () => {
  const hour = new Date().getHours()
  if (hour >= 6 && hour < 12) return "Good Morning"
  if (hour >= 12 && hour < 18) return "Good Afternoon"
  if (hour >= 18 && hour < 22) return "Good Evening"
  return "Good Night"
}

const handleSave = (note) => {
  editingNote.value = { ...note }
  saveNote()
}

const saveNote = async () => {
  try {
    const mutation = updateNoteMutation(editingNote.value)
    if (!mutation || !mutation.mutation) {
      throw new Error('Mutation is invalid or undefined')
    }
    const result = await client.mutate(mutation)
    isViewDialogOpen.value = false
  } catch (error) {
    console.error('Error saving note:', error)
    alert('Failed to save note: ' + error.message)
    isViewDialogOpen.value = false
  }
}

const viewFirstNote = async (lang) => {
  try {
    const notes = await fetchNotes(props.contact.requestType, lang)
    if (notes?.length > 0) {
      let note = notes[0].content
      note = note.replaceAll('@name', props.contact.name)
      note = note.replaceAll('@user', userStore.username)
      note = note.replaceAll('@dayparts', getGreeting())
      editingNote.value = {
        ...notes[0],
        content: notes[0].body || note,
      }
      isViewDialogOpen.value = true
    } else {
      snackbar.value = {
        show: true,
        message: "No notes available",
        color: "warning",
      }
    }
  } catch (error) {
    console.error('Note fetch error:', error)
    snackbar.value = {
      show: true,
      message: "Failed to load notes",
      color: "error",
    }
  }
}

const loadMessages = async () => {
  isLoading.value = true
  try {
    const template = await fetchMessageTemplates()
    messageOptions.value = template
    fetchError.value = false
  } catch (error) {
    console.error('Failed to load message templates:', error)
    fetchError.value = true
    messageOptions.value = []
  } finally {
    isLoading.value = false
  }
}

const openStatusDialog = () => {
  showStatusDialog.value = true
}

const handleStatusUpdate = (status, interaction, rating, id, phoneId) => {
  internalContact.value = {
    ...internalContact.value,
    id: id || internalContact.value.id,
    status,
    interaction,
    rating,
    phoneId,
  }
  props.onSave(internalContact.value)
  showStatusDialog.value = false
}

const deleteContact = () => {
  props.onDelete()
}

const handleKeydown = (event) => {
  if (event.key === '/') {
    isMenuActive.value = true
    filteredOptions.value = []
  }
}

const selectOption = (option) => {
  editContactData.value.interaction = editContactData.value.interaction.replace('/', option)
  isMenuActive.value = false
}

const handleSelectedProcessChange = (value) => {
  editContactData.value.process = value
  editContactData.value.stage = ""
  editContactData.value.task = ""
}

const handleSelectedStageChange = (value) => {
  editContactData.value.stage = value
  editContactData.value.task = ""
}

const handleSelectedTaskChange = (value) => {
  editContactData.value.task = value
}

const updateCallCount = () => {
  if (!isPhoneDisabled(editContactData.value)) {
    editContactData.value.called = (function (calledString) {
      const numberValue = parseInt(calledString, 10)
      return !isNaN(numberValue) ? numberValue + 1 : 1
    })(editContactData.value.called)
    editContactData.value.dialedDate = todayDDMMYYYY()
  }
}

const todayDDMMYYYY = () => {
  const date = new Date()
  const day = String(date.getDate()).padStart(2, '0')
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const year = date.getFullYear()
  return `${day}/${month}/${year}`
}

const handleCallClick = () => {
  updateCallCount()
  const newLogEntry = {
    name: editContactData.value.name,
    phoneNumber: editContactData.value.phoneNumber,
    dialedDate: todayDDMMYYYY(),
  }
  callLog.value.push(newLogEntry)
  if (callLog.value.length > 24) {
    callLog.value.shift()
  }
  localStorage.setItem('callLog', JSON.stringify(callLog.value))
  showStatusDialog.value = true
}

const confirmStatus = (index, selectedStatus, inte) => {
  if (!props.contacts || props.contacts.length === 0) {
    alert("error 329: Contacts Array is Empty!")
    return
  }
  if (!props.contacts[index]) {
    alert("error 115")
    console.error('Contact or selected status is undefined.')
    return
  }
  const localContacts = editContactData.value
  localContacts.status = `${selectedStatus} ${localContacts.status}`
  localContacts.interaction = inte
  localContacts.dialedDate = getTodayDate()
  localContacts.user = userStore.username
  localContacts.stage = "Qualify"
  localContacts.id = props.contact.id
  if (selectedStatus && selectedStatus.includes("tnt")) {
    localContacts.requestType = "tenanted"
  }
  props.onSave(localContacts)
  props.nextContact()
  showStatusDialog.value = false
}

const makeCall2 = async (contact, index, contacts) => {
  await viewFirstNote(selectedLanguage.value)
  await makeCall(contact, index, contacts)
}

const saveTaskToContact = async () => {
  try {
    const savedData = await editorRef.value.getSavedData()
    editContactData.value.task = savedData
  } catch (error) {
    console.error('Failed to get saved data:', error)
  }
}

const saveContact = async () => {
  if (!editContactData.value.requestType) {
    alert("Please select a Request Type before saving.")
    return
  }
  if (!editContactData.value.stage) {
    editContactData.value.stage = "Qualify"
  }
  loading.value = true
  await saveTaskToContact()
  props.onSave(editContactData.value)
  setTimeout(() => {
    snackbar.value.show = true
    loading.value = false
  }, 500)
}

const cancelEdit = () => {
  props.onCancel()
}

const updateValue = (newValue) => {
  editContactData.value.process = newValue.process
  editContactData.value.stage = newValue.stage
  editContactData.value.task = newValue.task
}

const { mutate: updateCallme } = useMutation(UPDATE_CALLME)

const makeCall = async (contact, currentIndex, contacts) => {
  try {
    let { name, doc, phoneNumber, status, interaction, lastCall, nextCall, no } = contact
    lastCall = convertDMY2YMDtime(lastCall, true)
    nextCall = convertDMY2YMDtime(nextCall, true)
    let selectedUser = userStore.username
    let id = 0
    if (selectedUser.toLowerCase() === "alyssa") id = 3
    if (selectedUser.toLowerCase() === "alvin") id = 1
    if (selectedUser.toLowerCase() === "ashton") id = 2
    const variables = {
      id: id,
      doc: doc,
      user: selectedUser,
      name: name,
      phoneNumber: phoneNumber,
      status: status,
      interaction: interaction,
      lastCall: lastCall,
      nextCall: nextCall,
      no: no,
    }
    updateCallCount()
    await updateCallme(variables)
  } catch (error) {
    alert("error 200")
    console.error('Error updating callme:', error.cause)
  }
}

const rowSendWhatsApp = (contact) => {
  if (!messageOptions.value.length) {
    alert('No message templates available')
    return
  }
  const optionsList = messageOptions.value
    .map((opt, idx) => `${idx}: ${opt.title} (${opt.category})`)
    .join('\n')
  const selectedIndex = prompt(`Select message template (0-${messageOptions.value.length - 1}):\n${optionsList}`)
  const index = parseInt(selectedIndex, 10)
  if (isNaN(index) || index < 0 || index >= messageOptions.value.length) {
    alert('Invalid selection')
    return
  }
  const selectedTemplate = messageOptions.value[index]
  let msg = selectedTemplate.message
  msg = msg.replace("@name", contact.name)
  if (selectedTemplate.id === 'custom') {
    const customMsg = prompt("Enter your custom message:")
    if (customMsg) {
      msg = customMsg
    } else {
      return
    }
  }
  const textarea = document.createElement('textarea')
  textarea.value = msg
  document.body.appendChild(textarea)
  textarea.select()
  document.execCommand('copy')
  document.body.removeChild(textarea)
  alert("Message copied to clipboard!")
  const { phoneNumber } = contact
  const cleanedPhoneNumber = cleanPhoneNumber(phoneNumber)
  const url = `https://api.whatsapp.com/send?phone=${cleanedPhoneNumber}&text=${encodeURIComponent(msg)}`
  window.open(url, '_blank')
  if (editContactData.value.doc.length > 0) {
    editContactData.value.doc += "," + selectedTemplate.id
  } else {
    editContactData.value.doc = selectedTemplate.id
  }
  if (!editContactData.value.contacted) {
    editContactData.value.contacted = 1
  }
  const today = new Date()
  const formattedDate = `${today.getDate().toString().padStart(2, '0')}/${(today.getMonth() + 1).toString().padStart(2, '0')}/${today.getFullYear()}`
  const interactionNote = `[${formattedDate}] Sent "${selectedTemplate.title}" via WhatsApp\n`
  editContactData.value.interaction = interactionNote + editContactData.value.interaction
  editContactData.value.doc += "," + selectedTemplate.id
  snackbar.value.show = true
  snackbar.value.message = "WhatsApp message sent successfully!"
}

// Watchers
watch(selectedLanguage, (newVal) => {
  localStorage.setItem('selectedLanguage', newVal)
})

watch(callLog, (newValue) => {
  localStorage.setItem('callLog', JSON.stringify(newValue))
})

watch(() => props.contact, (newContact) => {
  if (newContact) {
    internalContact.value = { ...newContact }
    editContactData.value.rating = ratingOptions.value.some(opt => opt.value === newContact.rating)
      ? newContact.rating
      : null
    editContactData.value = {
      id: newContact.id,
      name: newContact.name || '',
      phoneNumber: newContact.phoneNumber || '',
      language: newContact.language || 'en',
      lastCall: convertDMY2YMDtime(newContact.lastCall, true),
      nextCall: convertDMY2YMDtime(newContact.nextCall, true),
      no: newContact.no,
      interaction: newContact.interaction || '',
      doc: newContact.doc || '',
      status: newContact.status || '',
      rating: newContact.rating || 0,
      called: newContact.called || 0,
      contacted: newContact.contacted || 0,
      requestType: newContact.requestType || '',
      address: newContact.address || '',
      advUrl: newContact.advUrl || '',
      advUrlDate: newContact.advUrlDate || '',
      process: newContact.process || '',
      stage: newContact.stage || '',
      task: newContact.task || '',
      delegate: newContact.delegate || '',
      phoneId: newContact.phoneId || '',
      facebookUrl: newContact.facebookUrl || '',
      notionUrl: newContact.notionUrl || '',
    }
  }
  computeRatingOptions()
}, { immediate: true })

// Lifecycle hooks
onMounted(async () => {
  await loadMessages()
  const storedCallLog = localStorage.getItem('callLog')
  if (storedCallLog) {
    callLog.value = JSON.parse(storedCallLog)
  }
  const savedLang = localStorage.getItem('selectedLanguage')
  if (savedLang) selectedLanguage.value = savedLang
  computeRatingOptions()
  getDeviceInfo()
})
</script>

<style scoped>
.edit-mode {
  margin-bottom: 10px;
}

.sticky-buttons {
  position: sticky;
  top: 0;
  background: white;
  z-index: 1000;
  padding: 10px;
  border-bottom: 1px solid #ccc;
}

.btn-view-first {
  background-color: #4CAF50 !important;
  color: white !important;
  margin-left: 10px;
}

.info-with-template {
  position: relative;
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.template-selector {
  flex: 0 0 auto;
  display: flex;
  gap: 10px;
  align-items: center;
}

.info-textarea {
  flex: 1;
  width: auto;
}

.template-dropdown {
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: #fff;
  min-width: 150px;
}

.remove-button {
  padding: 8px 12px;
  border: 1px solid #dc3545;
  border-radius: 4px;
  background-color: #dc3545;
  color: white;
  cursor: pointer;
  white-space: nowrap;
}
</style>