<template>
  <tr>
    <td style="border: 1px solid #ccc; padding: 8px;">
      <select v-model="item.advertiser" @change="updateItem">
        <option v-for="option in ['Mudah', 'iProperty', 'TRR Broker', 'EUM Broker', 'TITAN Broker', 'Signage']" :key="option" :value="option">{{ option }}</option>
      </select>
    </td>
    <td style="border: 1px solid #ccc; padding: 8px;">
      <input v-model="item.url" @input="updateItem" style="width: 100%;" />
    </td>
    <td style="border: 1px solid #ccc; padding: 8px;">
      <input type="date" v-model="item.date" @input="updateItem" style="width: 100%;" />
    </td>
    <td style="border: 1px solid #ccc; padding: 8px; text-align: center;">
      <button @click="$emit('remove', index)" class="nice-button">Remove</button>
    </td>
  </tr>
</template>

<script>
export default {
  props: {
    item: Object,
    index: Number
  },
  methods: {
    updateItem() {
      console.log('Item updated:', this.item);
      this.$emit('update:item', { index: this.index, item: { ...this.item } });
    }
  }
};
</script>

<style scoped>
select, input {
  border: 2px solid blue; /* Make elements visible for debugging */
}
</style>