<template>
  <div>
    <h1>Leads Cards</h1>
    <div class="card-container">
      <div class="card" v-for="lead in leads" :key="lead.id">
        <h2> {{ formatRequestType(lead.requestType) }}</h2>
        <p><strong>info:</strong> {{ lead.info }}</p>
        <p><strong>Location:</strong> {{ lead.location }}</p>
        <p><strong>District:</strong> {{ lead.district }}</p>
        <hr/>
        <p>{{ lead.id }}</p>
        <p><strong>Name:</strong> {{ lead.name }}</p>
        <p><strong>phoneNumber:</strong> {{ lead.phoneNumber }}</p>
        <p><strong>Interaction:</strong> {{ lead.interaction }}</p>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 1em;">
              <thead>
                <tr>
                  <th style="border: 1px solid #ccc; padding: 0px; width: 100%;"  colspan="2">Task</th>
                  <!-- <th style="border: 1px solid #ccc; padding: 8px; width: 15%;">Date</th>
                  <th style="border: 1px solid #ccc; padding: 8px; width: 5%;">Actions</th> -->
                </tr>
              </thead>
              <tbody>
                <tr v-for="(action, index) in lead.actions" :key="index">
                  <td style="border: 1px solid #ccc; padding: 8px; width: 100%;">
                     {{ action.task }}
                    <!-- <textarea v-model="action.task" placeholder="Task" class="e-input"
                      style="width: 100%; height: auto; resize: vertical; overflow-wrap: break-word;">
                    </textarea> -->
                  </td>
                  <td style="border: 1px solid #ccc; padding: 8px; width: 100%;">
                    {{ action.status }}
                  </td>
                  <!-- <td style="border: 1px solid #ccc; padding: 8px;">
                    <input type="date" v-model="action.date" class="e-input" style="width: 100%;" />
                  </td>
                  <td style="border: 1px solid #ccc; padding: 8px; text-align: center;">
                    <button @click="removeAction(index)" class="nice-button">Remove</button>
                  </td> -->
                </tr>
              </tbody>
            </table>
       
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 1em;">
              <thead>
                <tr>
                  <th style="border: 1px solid #ccc; padding: 0px; width: 100%;">
                    <label @click="toggleImageVisibility" style="cursor: pointer;">Document</label>
                  </th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(doc, index) in lead.documents" :key="index">
                  <td>
                    <div class="document-container">
                      <!-- Thumbnail container -->
                      <div class="thumbnail-container" :title="doc.url" v-show="showImage">
                        <!-- Show file type icon based on URL extension -->
                        <img 
                          :src="doc.url" 
                          class="document-thumbnail"
                          :alt="getFileType(doc.url)"
                        />
                        <!-- Truncated filename -->
                     
                      </div>
                      <!-- Description -->
                      <p class="description">{{ doc.description }}</p>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>

            <table style="width: 100%; border-collapse: collapse; margin-bottom: 1em;">
              <thead>
                <tr>
                  <th style="border: 1px solid #ccc; padding: 0px; width: 100%;">Advertisement</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(action, index) in lead.advertisers" :key="index">
                  <td style="white-space: nowrap; text-overflow:ellipsis; overflow: hidden; max-width:1px;">
                     {{ action.advertiser }}
                  </td>
                  
                </tr>
              </tbody>
            </table>
      
      </div>
    </div>
  </div>
</template>

<script>
import { gql } from '@apollo/client/core';
import client from '../apollo-client';

export default {
  name: 'LeadsList',
  data() {
    return {
      leads: [], // Store leads data
      showImage: false
    };
  },
  methods: {
    toggleImageVisibility() {
      this.showImage = !this.showImage;
    },
    getFileIcon(url) {
      // Get file extension from URL
      const extension = url.split('.').pop().toLowerCase()
      
      // Return appropriate icon based on file type
      switch(extension) {
        case 'pdf':
          return '/icons/pdf.png'
        case 'doc':
        case 'docx':
          return '/icons/word.png'
        case 'xls':
        case 'xlsx':
          return '/icons/excel.png'
        case 'jpg':
        case 'jpeg':
        case 'png':
          return url // Use actual image for image files
        default:
          return '/icons/file.png'
      }
    },
    getFileType(url) {
      const extension = url.split('.').pop().toLowerCase()
      return extension.toUpperCase()
    },
    getFileName(url) {
      // Extract filename from URL
      const fileName = url.split('/').pop()
      // Truncate if too long
      return fileName.length > 20 
        ? fileName.substring(0, 17) + '...' 
        : fileName
    },

    // Format status for display
    
    // Format requestType for display
    formatRequestType(requestType) {
      switch (requestType) {
        case 'buyer':
          return 'Want to Buy';
        case 'seller':
          return 'Want to Sell';
        case 'rent':
          return 'Want to Rent';
        case 'lease':
          return 'Want to Lease';
        default:
          return 'Unknown Request';
      }
    },
  },
  async created() {
    try {
      const { data } = await client.query({
        query: gql`
        query {
              leads(
              filters: { 
                rating: { gt: 2 }, 
                requestType: { notIn: ["task", "project_seller","project_buyer"] } 
              },
              pagination: { limit: 1000 }
              sort: ["requestType:desc", "status:desc"]
            ) {
              data {
                id
                attributes {
                  name
                  phoneNumber
                  interaction
                  called
                  status
                  location
                  requestType
                  district
                  advertisement
                  {
                   advertiser
                   url
                   date 
                  }
                  document{
                    description
                    url
                  }
                  action{
                    task
                    status
                    date
                  }
                }
              }
            }
          }
        `,
        fetchPolicy: 'no-cache',
      });

      // Map API response to the desired structure
      this.leads = data.leads.data.map((lead) => ({
        id: lead.id,
        name: lead.attributes.name,
        phoneNumber: lead.attributes.phoneNumber || 'N/A',
        interaction: lead.attributes.interaction || 'N/A',
        called: lead.attributes.called || false,
        status: lead.attributes.status || 'pending',
        requestType: lead.attributes.requestType || 'Unknown',
        location: lead.attributes.location || 'Unknown',
        district: lead.attributes.district || 'Unknown',
        actions: lead.attributes.action || [],
        documents: lead.attributes.document || [],
        advertisers: lead.attributes.advertiser || [],
      }));
    } catch (error) {
      console.error('Error fetching leads:', error);
      alert('Failed to load leads data. Please try again.');
    }
  },
};
</script>

<style>
.card-container {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 16px;
}

.card {
  background-color: #f9f9f9;
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 16px;
  width: 300px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2); /* Updated shadow */
  transition: transform 0.2s, box-shadow 0.2s, background-color 0.2s;
}

.card:hover {
  transform: scale(1.05); /* Slightly larger hover effect */
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.3); /* Stronger shadow on hover */
  background-color: #f0f8ff;
}

.card h2 {
  margin: 0 0 8px;
  font-size: 18px;
  color: #333;
}

.card p {
  margin: 4px 0;
  font-size: 14px;
  color: #555;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 1em;
}

.data-table th,
.data-table td {
  border: 1px solid #ccc;
  padding: 8px;
}

.document-container {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.thumbnail-container {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px;
  border-radius: 4px;
  background: #f5f5f5;
  cursor: pointer;
}

.thumbnail-container:hover {
  background: #eee;
}

.document-thumbnail {
  width: 48px;
  height: 48px;
  object-fit: contain;
}

.filename {
  font-size: 0.9em;
  color: #333;
}

.description {
  font-size: 0.85em;
  color: #666;
  margin: 0;
}
</style>
