<template>
  <h1>Leads Report</h1>
  <v-row>
    <v-col>
      <v-container>
        <div class="legend">
          <p><strong>Legend:</strong></p>
          <v-row class="align-center">
            <v-col cols="auto" class="d-flex align-center">
              <v-icon color="green" class="mr-2">mdi-checkbox-blank-circle</v-icon>
              <span>In Progress</span>
            </v-col>
            <v-col cols="auto" class="d-flex align-center">
              <v-icon color="purple" class="mr-2">mdi-checkbox-blank-circle</v-icon>
              <span>On Hold</span>
            </v-col>
            <v-col cols="auto" class="d-flex align-center">
              <v-icon class="mr-2">mdi-format-strikethrough</v-icon>
              <span>Done</span>
            </v-col>
          </v-row>
        </div>
      </v-container>
    </v-col>
  </v-row>
  <v-simple-table class="grid-table">
    <template v-slot:default>
      <thead>
        <tr>
          <th>Project</th>
          <th>RequestType</th>
          <th>Stage</th>
          <th>Assignee</th>
          <th>Rating</th>
          <th>Name</th>
          <th>Phone ID</th>
          <th>Phone Number</th>
          <th>Action</th>
          <th>Interaction</th>
          <th>Create Date</th>
          <th>Updated Date</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="lead in leads" :key="lead.id">
          <td>{{ lead.project }}</td>
          <td>{{ lead.requestType }}</td>
          <td>{{ lead.stage }}</td>
          <td>{{ lead.assignee }}</td>
          <td>{{ lead.rating }}</td>
          <td width="200">{{ lead.name }}</td>
          <td width="70">{{lead.phoneId}}</td>
          <td>{{ lead.phoneNumber }}</td>
          
          <td class="narrow-column">
            <div v-for="action in lead.actions" :key="action.date + '-' + action.task + '-' + action.status">
              {{ action.date }} - 
              <span :style="{
                textDecoration: action.status === 'Done' ? 'line-through' : 'none',
                color: 
                  action.status === 'In_Progress' ? 'green' : 
                  action.status === 'On_Hold' ? 'darkmagenta' : 
                  'inherit'
              }">
                {{ action.task }}
              </span> 
              
            </div>
          </td>
          <td>{{ lead.interaction }}</td>
          <td>{{ new Date(lead.createdAt).toLocaleDateString('en-GB') }}</td>
          <td>{{ new Date(lead.updatedAt).toLocaleDateString('en-GB') }}</td>
        </tr>
      </tbody>
    </template>
  </v-simple-table>
</template>

<script>
import { gql } from '@apollo/client/core';
import client from '../apollo-client';

export default {
name: 'LeadsReport',
props: {
  sortFields: {
    type: Array,
    default: () => ["project", "requestType", "name"],
    validator: value => {
      const validFields = ["project", "requestType", "stage", "name", "phoneNumber", "interaction","assignee","createdAt","updatedAt"];
      return value.every(field => validFields.includes(field));
    }
  }
},
data() {
  return {
    leads: [], // Store leads data
  };
},
methods: {
  async fetchLeads() {
    try {
      const { data } = await client.query({
        query: gql`
          query GetLeads($sort: [String]) {
            leads(
              filters: { action: { date: { notNull: true } } }
              pagination: { limit: 1000 }
              sort: $sort
            ) {
              data {
                id
                attributes {
                  project
                  requestType
                  stage
                  assignee
                  rating
                  name
                  phoneNumber
                  phoneId
                  createdAt
                  updatedAt
                  action {
                    date
                    task
                    status
                  }
                  interaction
                }
              }
            }
          }
        `,
        variables: {
          sort: this.sortFields
        },
        fetchPolicy: 'no-cache',
      });

      // Map the API response to desired structure
      this.leads = data.leads.data.map((lead) => ({
        project: lead.attributes.project,
        stage: lead.attributes.stage,
        rating: lead.attributes.rating,
        assignee: lead.attributes.assignee,
        phoneId:lead.attributes.phoneId,
        requestType: lead.attributes.requestType,
        id: lead.id,
        name: lead.attributes.name,
        phoneNumber: lead.attributes.phoneNumber,
        actions: lead.attributes.action || [], // Handle empty actions gracefully
        interaction: lead.attributes.interaction,
        createdAt:lead.attributes.createdAt,
        updatedAt:lead.attributes.updatedAt
      }));
    } catch (error) {
      console.error('Error fetching leads:', error);
      alert('Failed to load leads data. Please try again.');
    }
  }
},
async created() {
  await this.fetchLeads();
},
watch: {
  sortFields: {
    handler: 'fetchLeads',
    deep: true
  }
}
};
</script>

<style scoped>
.legend ul {
list-style-type: none;
padding: 0;
}

.legend li {
margin-bottom: 0.5em;
}

.grid-table {
border-collapse: collapse;
}

.grid-table th, .grid-table td {
border: 1px solid #ddd;
}

.grid-table thead th {
background-color: #f2f2f2;
}

.narrow-column {
width: 10px;
white-space: nowrap;
overflow: hidden;
text-overflow: ellipsis;
}

.legend ul {
list-style-type: none;
padding-left: 0;
}

.legend li {
display: flex;
align-items: center;
margin-bottom: 0.5em;
}

.legend li v-icon {
margin-right: 0.5em;
}
</style>