<template>
  <dialog :open="isDialogOpen" class="editor-dialog">
    <div v-if="isDialogOpen" class="dialog-content">
      <h2>{{ isEditing ? 'Edit Note' : 'Create New Note' }}</h2>
      <form @submit.prevent="handleSave">
        <div class="form-group form-row">
          <div class="field-group">
            <label>Title:</label>
            <input v-model="localNote.title" required />
          </div>
          <div class="field-group">
            <label>Language:</label>
            <select v-model="localNote.language" required>
              <option value="en">en</option>
              <option value="cn">cn</option>
              <option value="ct">ct</option>
              <option value="bm">bm</option>
            </select>
          </div>
          <div class="field-group">
            <label>Request Type:</label>
            <select v-model="localNote.requestType" required>
              <option value="buyer">Buyer</option>
              <option value="project_buyer">Project Buyer</option>
              <option value="project_seller">Project Seller</option>
              <option value="seller">Seller</option>
              <option value="lease">Lease</option>
              <option value="rent">Rent</option>
              <option value="owner">Owner</option>
            </select>
          </div>
        </div>
        <div class="form-group">
          <Editor
            v-if="shouldShowEditor"
            api-key="n9a3k2ct7m8zi0jndx3htzxbpug1lng0fkql2ofx8ligz5gm"
            v-model="localNote.content"
            :init="editorConfig"
            initial-value="Welcome to TinyMCE!"
          />
        </div>
        <div class="action-buttons">
          <button type="button" @click="handleClose" class="btn-cancel">Cancel</button>
          <button type="submit" class="btn-save">
            {{ isEditing ? 'Update' : 'Create' }}
          </button>
        </div>
      </form>
    </div>
  </dialog>
</template>

<script setup>
import { ref, watch, onUnmounted } from 'vue';
import Editor from '@tinymce/tinymce-vue';

const props = defineProps({
  open: { type: Boolean, required: true },
  note: { type: Object, default: null },
  isEditing: { type: Boolean, default: false }
});

const emit = defineEmits(['save', 'close']);

const isDialogOpen = ref(false);
const shouldShowEditor = ref(false);
const localNote = ref({
  title: '',
  content: '',
  language: 'english',
  requestType: 'buyer'
});

const handleImageUpload = (blobInfo) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = error => reject(error);
    reader.readAsDataURL(blobInfo.blob());
  });
};

const handleSave = () => {
  emit('save', { ...localNote.value });
  handleClose();
};

const handleClose = () => {
  shouldShowEditor.value = false;
  isDialogOpen.value = false;
  resetNote();
  emit('close');
};

const resetNote = () => {
  localNote.value = {
    title: '',
    content: '',
    language: 'english',
    requestType: 'buyer'
  };
};

const editorConfig = {
  height: 700,
  menubar: true,
  toolbar_mode: 'sliding',
  plugins: [
    'code', 'preview', 'anchor', 'autolink', 'charmap', 'codesample', 
    'emoticons', 'image', 'link', 'lists', 'media', 'searchreplace', 'table', 
    'visualblocks', 'wordcount', 'checklist', 'mediaembed', 'casechange', 
    'export', 'formatpainter', 'pageembed', 'a11ychecker', 'tinymcespellchecker', 
    'permanentpen', 'powerpaste', 'advtable', 'advcode', 'editimage', 
    'advtemplate', 'mentions', 'tableofcontents', 'footnotes', 'mergetags', 
    'autocorrect', 'typography', 'inlinecss', 'importword', 'exportword', 'exportpdf'
  ],
  toolbar: 'undo redo | styleselect | bold italic underline | alignleft aligncenter alignright alignjustify | ' +
           'bullist numlist outdent indent | link image media table | ' +
           'forecolor backcolor emoticons',
  valid_elements: '*[*]', // Allows all HTML elements
  content_style: 'body { font-family:Helvetica,Arial,sans-serif; font-size:14px }',
  placeholder: 'Enter note content here...',
  tinycomments_mode: 'embedded',
  tinycomments_author: 'Author name',
  images_upload_handler: handleImageUpload,
};

watch(() => props.open, (newVal) => {
  if (newVal) {
    isDialogOpen.value = true;
    shouldShowEditor.value = true;
  } else {
    shouldShowEditor.value = false;
    isDialogOpen.value = false;
  }
});

watch(() => props.note, (newVal) => {
  if (newVal) {
    localNote.value = { 
      ...newVal,
      language: newVal.language || 'english',
      requestType: newVal.requestType || 'buyer'
    };
  } else {
    resetNote();
  }
}, { immediate: true });

onUnmounted(() => {
  shouldShowEditor.value = false;
  isDialogOpen.value = false;
});
</script>

<style scoped>
.editor-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80%; /* Adjust as needed */
  max-width: 800px; /* Optional: limit max width */
  border: 1px solid #ccc;
  border-radius: 8px;
  background: white;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
  z-index: 1000; /* Ensure it’s above other content */
}

.editor-dialog:not([open]) {
  display: none;
}

.dialog-content {
  padding: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.form-row {
  flex-direction: row;
  gap: 20px;
  align-items: flex-start;
}

.field-group {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.field-group label {
  font-weight: 500;
  margin-bottom: 5px;
}

.field-group input,
.field-group select {
  width: 100%;
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 4px;
}

.action-buttons {
  margin-top: 20px;
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.btn-cancel {
  padding: 8px 16px;
  background: #f5f5f5;
  border: 1px solid #ddd;
  cursor: pointer;
}

.btn-save {
  padding: 8px 16px;
  background: #2196F3;
  color: white;
  border: none;
  cursor: pointer;
}

:deep(.tox-editor-container) {
  min-height: 200px;
  margin-top: 15px;
}
</style>