<!-- InfoSection.vue -->
<template>
  <div class="card-info-section">
    <h4>Info:</h4>
    <div class="info-with-template">
      <textarea 
        v-model="infoData" 
        placeholder="Enter additional info..." 
        class="info-textarea"
        @input="emitUpdate"
      ></textarea>
      <div class="template-selector">
        <select 
          @change="applyTemplate($event)"
          class="template-dropdown"
        >
          <option value="">Select Template</option>
          <option 
            v-for="(template, index) in tenantProfiles" 
            :key="index" 
            :value="index"
          >
            {{ `${template[0]} - ${template[1]}` }}
          </option>
        </select>
        <button 
          @click="removeExampleData"
          class="remove-button"
        >
          Remove Example
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

const props = defineProps({
info: {
  type: String,
  default: ''
},
tenantProfiles: {
  type: Array,  // Corrected from {object} to Array
  default: () => []  // Added default value as empty array
}
})

const emit = defineEmits(['update:info'])

const infoData = ref(props.info)

watch(() => props.info, (newVal) => {
infoData.value = newVal
})

const applyTemplate = (event) => {
const selectedIndex = event.target.value
if (selectedIndex !== "") {
  infoData.value = props.tenantProfiles[selectedIndex][2]
  event.target.value = ""
  emitUpdate()
}
}

const removeExampleData = () => {
if (infoData.value) {
  infoData.value = infoData.value.replace(/^(.+?:).*$/gm, '$1 ')
  emitUpdate()
}
}

const emitUpdate = () => {
emit('update:info', infoData.value)
}
</script>

<style scoped>
.card-info-section {
margin-bottom: 20px;
}

.card-info-section h4 {
margin-bottom: 10px;
color: #333;
}

.info-textarea {
width: 100%;
height: 100px;
padding: 10px;
border: 1px solid #ccc;
border-radius: 4px;
background-color: #f8f9fa;
resize: vertical;
}

.info-with-template {
position: relative;
display: flex;
gap: 10px;
align-items: flex-start;
}

.template-selector {
flex: 0 0 auto;
display: flex;
gap: 10px;
align-items: center;
}

.template-dropdown {
padding: 8px;
border: 1px solid #ccc;
border-radius: 4px;
background-color: #fff;
min-width: 150px;
}

.remove-button {
padding: 8px 12px;
border: 1px solid #dc3545;
border-radius: 4px;
background-color: #dc3545;
color: white;
cursor: pointer;
white-space: nowrap;
}

.remove-button:hover {
background-color: #c82333;
}

.info-textarea {
flex: 1;
width: auto;
}
</style>