<template>
  <div>
    <h2>tiny MCE</h2>
    <!-- Main Content (hidden when dialogs are open) -->
    <div v-show="!isAnyDialogOpen">
      <v-btn color="primary" @click="openCreateDialog" class="mb-4">
        Add New Note
      </v-btn>

      <v-data-table
        :headers="headers"
        :items="notes"
        :items-per-page="10"
        class="elevation-1"
      >
        <template v-slot:item.actions="{ item }">
          <v-btn
            small
            color="info"
            class="mr-2"
            width="100px"
            @click="openViewDialog(item)"
          >
            <v-icon>mdi-eye</v-icon>
          </v-btn>
          <v-btn
            small
            color="warning"
            class="mr-2"
            width="100px"
            @click="openEditDialog(item)"
          >
            <v-icon>mdi-pencil</v-icon>
          </v-btn>
          <v-btn
            small
            color="error"
            width="100px"
            @click="deleteNote(item.id)"
          >
            <v-icon>mdi-delete</v-icon>
          </v-btn>
        </template>
      </v-data-table>
    </div>

    <!-- View Dialog -->
    <NoteViewDialog
      :open="isViewDialogOpen"
      :note="viewedNote"
      @close="isViewDialogOpen = false"
    />

    <!-- Editor Dialog -->
    <note-editor-dialog 
      :open="isDialogOpen" 
      :note="editingNote" 
      :is-editing="isEditing" 
      @save="handleSave"
      @close="closeDialog" 
    />
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue';
import { gql } from '@apollo/client/core';
import client from '../apollo-client';
import NoteEditorDialog from './NoteEditorDialog.vue';
import NoteViewDialog from './NoteViewDialog.vue';
import { updateNoteMutation } from '../utils/vgraphql.js';

// Reactive state
const isDialogOpen = ref(false);
const notes = ref([]);
const isViewDialogOpen = ref(false);
const isEditing = ref(false);
const viewedNote = ref(null);
const editingNote = ref(null);

// Headers definition
const headers = [
  { title: 'Title', value: 'title' },
  { title: 'Language', value: 'language' },
  { title: 'Request Type', value: 'requestType' },
  { title: 'Actions', value: 'actions', sortable: false, width: '350px' }
];

// Computed properties
const isAnyDialogOpen = computed(() => {
  return isViewDialogOpen.value || isDialogOpen.value;
});

// Methods
const handleSave = (note) => {
  editingNote.value = { ...note };
  saveNote();
};

const openCreateDialog = () => {
  isEditing.value = false;
  editingNote.value = {
    title: '',
    content: '',
    language: 'english',
    requestType: ''
  };
  isDialogOpen.value = true;
};

const fetchNotes = async () => {
  try {
    const { data } = await client.query({
      query: gql`
        query Notes {
          notes {
            data {
              id
              attributes {
                title
                content
                language
                requestType
              }
            }
          }
        }
      `,
      fetchPolicy: 'network-only'
    });

    notes.value = data.notes.data.map(note => ({
      id: note.id,
      title: note.attributes.title,
      language: note.attributes.language,
      content: note.attributes.content,
      requestType: note.attributes.requestType
    }));
  } catch (error) {
    console.error('Error fetching notes:', error);
    alert('Failed to fetch notes');
  }
};

const openViewDialog = (note) => {
  viewedNote.value = { ...note };
  isViewDialogOpen.value = true;
};

const openEditDialog = (note) => {
  isEditing.value = true;
  editingNote.value = { ...note };
  isDialogOpen.value = true;
};

const closeDialog = () => {
  isDialogOpen.value = false;
  editingNote.value = null;
  isEditing.value = false;
};

const saveNote = async () => {
  try {
    console.log('isEditing:', isEditing.value);
    console.log('editingNote:', editingNote.value);
    const mutation = isEditing.value ? updateNoteMutation(editingNote.value) : createNoteMutation();
    console.log('Mutation object:', mutation);
    if (!mutation || !mutation.mutation) {
      throw new Error('Mutation is invalid or undefined');
    }
    const result = await client.mutate(mutation);
    console.log('Mutation result:', result);
    await fetchNotes();
    closeDialog();
  } catch (error) {
    console.error('Error saving note:', error);
    alert('Failed to save note: ' + error.message);
    closeDialog();
  }
};

const createNoteMutation = () => {
  return {
    mutation: gql`
      mutation CreateNote($input: NoteInput!) {
        createNote(data: $input) {
          data {
            id
            attributes {
              title
              content
              language
              requestType
            }
          }
        }
      }
    `,
    variables: {
      input: {
        title: editingNote.value.title,
        content: editingNote.value.content,
        language: editingNote.value.language,
        requestType: editingNote.value.requestType
      }
    }
  };
};

const deleteNote = async (id) => {
  if (!confirm('Are you sure you want to delete this note?')) return;

  try {
    await client.mutate({
      mutation: gql`
        mutation DeleteNote($id: ID!) {
          deleteNote(id: $id) {
            data {
              id
            }
          }
        }
      `,
      variables: { id }
    });
    fetchNotes();
  } catch (error) {
    console.error('Error deleting note:', error);
    alert('Failed to delete note');
  }
};

// Lifecycle hooks
onMounted(() => {
  fetchNotes();
});
</script>

<style scoped>
.mb-4 {
  margin-bottom: 16px;
}
</style>