<template>
  <div class="view-lease">

    <v-btn color="red" @click="closeView">Close</v-btn>
    <h2>View Lease</h2>
    <p v-if="loading">Loading...</p>
    <p v-if="error">Error: {{ error.message }}</p>
    <div v-if="lease">
      <p>Name: {{ lease.name || 'N/A' }}</p>
      <p>Location: {{ lease.location || 'N/A' }}</p>
      <p>Address: {{ lease.address || 'N/A' }}</p>
      <p>District: {{ lease.district || 'N/A' }}</p>
      <p>Lease From: {{ lease.leaseFrom || 'N/A' }}</p>
      <p>Lease To: {{ lease.leaseTo || 'N/A' }}</p>
      <p>Monthly Rental: {{ lease.monthlyRental || 'N/A' }}</p>
      <p>Rating: {{ lease.rating || 'N/A' }}</p>
      <p>Assignee: {{ lease.assignee || 'N/A' }}</p>
      <p>Interaction: {{ lease.interaction || 'N/A' }}</p>
      <p>Remark: {{ lease.remark || 'N/A' }}</p>
      <p>Info: {{ lease.info || 'N/A' }}</p>
      <p>Car Park: {{ lease.carPark || 'N/A' }}</p>
      <p>Co-Broked: {{ lease.coBroked ? 'Yes' : 'No' }}</p>
      <p>Appointment Date: {{ lease.AppointmentDate || 'N/A' }}</p>
      <p>Stage: {{ lease.stage || 'N/A' }}</p>
      <p>Request Type: {{ lease.requestType || 'N/A' }}</p>
      <div v-if="lease.document && lease.document.length">
        <h3>Documents:</h3>
        <ul>
          <li v-for="doc in lease.document" :key="doc.url">
            <a :href="doc.url" target="_blank">{{ doc.description || 'View Document' }}</a>
          </li>
        </ul>
      </div>
    </div>
    <p v-else-if="!loading && !error">No lease data available.</p>
  </div>
</template>

<script>
import { ref, onMounted, watch } from 'vue';
import { loadSingleLease } from '../utils/vgraphql';
import { useRouter } from 'vue-router';

export default {
  props: ['id'],
  emits: ['close'],
  setup(props) {
    const lease = ref(null);
    const loading = ref(true);
    const error = ref(null);
    const router = useRouter(); // Access Vue Router
    
    const fetchLease = async (leaseId) => {
      try {
        console.log('Fetching lease with ID:', leaseId);
        const fetchedLease = await loadSingleLease(leaseId);
        console.log('Fetched lease data:', fetchedLease);
        if (fetchedLease.length > 0) {
          lease.value = fetchedLease[0].data.attributes;
        } else {
          lease.value = null;
        }
        loading.value = false;
      } catch (fetchError) {
        console.error('Error fetching lease:', fetchError);
        error.value = fetchError;
        loading.value = false;
      }
    };

    onMounted(() => {
      console.log('Component mounted with ID:', props.id);
      if (props.id) {
        fetchLease(props.id);
      }
    });

    watch(() => props.id, (newLeaseId) => {
      console.log('ID changed to:', newLeaseId);
      if (newLeaseId) {
        fetchLease(newLeaseId);
      } else {
        lease.value = null;
        loading.value = false;
      }
    });

    const closeView = () => {
      router.back(); // Go back to the previous page
    };
    return { lease, loading, error,closeView };
  },
};
</script>

<style scoped>
.view-lease {
  border: 1px solid #ccc;
  padding: 10px;
  margin: 10px;
}
</style>
