<template>
  <div class="salesFunnel">
    <!-- Filters and Buttons -->
    <div class="filter-container">
      <v-row class="filter-row" no-gutters align="center">
        <v-col cols="6" sm="1" class="filter-col">
          <v-select v-model="selectedYear" :items="years" item-title="text" item-value="value" label="Year" dense
            @update:modelValue="fetchDialingData" class="ma-1 narrow-select"></v-select>
        </v-col>
        <v-col cols="6" sm="1" class="filter-col">
          <v-select v-model="selectedMonth"
            :items="[{ value: '', text: '-' }, ...months.map(m => ({ value: m.value, text: m.label }))]"
            item-title="text" item-value="value" label="Month" dense @update:modelValue="fetchDialingData"
            class="ma-1 narrow-select"></v-select>
        </v-col>
        <v-col cols="6" sm="1" class="filter-col">
          <v-select v-model="selectedDay" :items="[{ value: '', text: '-' }, ...days]" item-title="text"
            item-value="value" label="Day" dense @update:modelValue="fetchDialingData" class="ma-1 narrow-select"
            :disabled="!selectedMonth"></v-select>
        </v-col>
        <v-col cols="6" sm="2" class="filter-col">
          <v-select v-model="selectedProject"
            :items="[{ value: '', text: '-' }, { value: 'All > 0', text: '- > 0' }, { value: 'All > 3 < 11', text: '- > 3 < 11' }, ...projects.map(p => ({ value: p, text: p }))]"
            item-title="text" item-value="value" label="Project" dense @update:modelValue="fetchDialingData"
            class="ma-1"></v-select>
        </v-col>
        <v-col cols="6" sm="2" class="filter-col">
          <v-select v-model="selectedCompany"
            :items="[{ value: '', text: '-' }, ...companies.map(c => ({ value: c, text: c }))]" item-title="text"
            item-value="value" label="Company" dense @update:modelValue="fetchDialingData" class="ma-1"></v-select>
        </v-col>
        <v-col cols="6" sm="2" class="filter-col">
          <v-select v-model="selectedPhoneId"
            :items="[{ value: '', text: '-' }, { value: 'blank', text: 'Blank' }, ...phoneIds.map(id => ({ value: id, text: id }))]"
            item-title="text" item-value="value" label="Phone ID" dense @update:modelValue="fetchDialingData"
            class="ma-1"></v-select>
        </v-col>
        <v-col cols="6" sm="1" class="filter-col">
          <v-checkbox v-model="showAssignee" label="Show Assignee" dense class="ma-1 checkbox-tight"></v-checkbox>
        </v-col>
        <v-col cols="6" sm="2" class="filter-col">
          <div class="button-group">
            <v-btn @click="fetchDialingData" color="success" class="ma-1 narrow-btn" small dense>Load</v-btn>
            <v-btn @click="printPDF" color="primary" class="ma-1 narrow-btn" small dense>Print PDF</v-btn>
          </div>
        </v-col>
      </v-row>
    </div>
    <!-- Popup Dialog for Default Phone ID Selection -->
    <v-dialog v-model="showDefaultPhoneIdDialog" persistent max-width="400px">
      <v-card>
        <v-card-title>Select Default Phone ID</v-card-title>
        <v-card-text>
          <v-select v-model="defaultPhoneStore.defaultPhoneId"
            :items="defaultPhoneStore.phoneIds.map(id => ({ value: id, text: id }))" item-title="text"
            item-value="value" label="Please select a Default Phone ID"
            @update:modelValue="handleDefaultPhoneIdChange"></v-select>
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="saveDefaultPhoneId">Save</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
    <v-alert v-if="loading" type="info" class="mb-4">Loading dialing data...</v-alert>
    <v-alert v-else-if="error" type="error" class="mb-4">{{ error }}</v-alert>
    <div v-else>
      <div class="kpi-row">
        <div class="kpi-item">
          <span class="kpi-label">Total Dials:</span>
          <span class="kpi-value">{{ totalDials }}</span>
        </div>
        <div class="kpi-item">
          <span class="kpi-label">Total Backlog:</span>
          <span class="kpi-value">{{ totalBacklog }}</span>
        </div>
        <div class="kpi-item">
          <span class="kpi-label">Total Records:</span>
          <span class="kpi-value">{{ totalRecords }}</span>
        </div>
        <div class="kpi-item">
          <span class="kpi-label">Fetched:</span>
          <span class="kpi-value">{{ totalRecordsFetch }}</span>
          
        </div>
        <v-btn 
            @click="showWantToRecords" 
            color="warning" 
            class="ma-1 narrow-btn" 
            small 
            dense
            width="200px"
          >
            Want To
          </v-btn>
      </div>

      <!-- Data Table -->
      <v-data-table :headers="headers" :items="tableItems" :items-per-page="-1" class="elevation-1">
        <!-- Custom Header with Totals -->
        <template v-for="header in headers" #[`header.${header.value}`]="{ column }">
          <div class="header-wrapper">
            <button 
              v-if="header.value !== 'date' && header.value !== 'project' && header.value !== 'assignee'" 
              @click="showDetailedRecords(header.value)" 
              :class="getHeaderClass(header.value)"
            >
              {{ column?.title || '--' }}
              <span class="total-badge">{{ calculateTotal(header.value, tableItems) }}</span>
            </button>
            <span v-else class="non-clickable-header">
              {{ column?.title || '--' }}
              <span class="total-badge">{{ calculateTotal(header.value, tableItems) }}</span>
            </span>
          </div>
        </template>

        <template v-slot:bottom>
          <div class="text-center pt-2">
          
          </div>
        </template>
        <!-- Item Slots  rating change-->
        <template v-slot:item.date="{ item }">
          <span>{{ item.date || 'N/A' }}</span>
        </template>
        <template v-slot:item.project="{ item }">
          <span>{{ item.project }}</span>
        </template>
        <template v-slot:item.assignee="{ item }">
          <span v-if="showAssignee">{{ item.assignee || 'N/A' }}</span>
        </template>
        <template v-slot:item.totalRecords="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'totalRecords')">{{ item.totalRecords }}</span>
        </template>
        <template v-slot:item.totalDials="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'totalDials')"
            :title="`Verify count: ${item.totalDials}`">{{ item.totalDials }}</span>
        </template>
        <template v-slot:item.backlog="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'backlog')">{{ item.backlog }}</span>
        </template>
        <template v-slot:item.rated_undialed="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'rated_undialed')">{{ item.rated_undialed }}</span>
        </template>
        <template v-slot:item.failed="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'failed')">{{ item.failed }}</span>
        </template>
        <template v-slot:item.whatsapp_send="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'whatsapp_send')">{{ item.whatsapp_send }}</span>
        </template>
        <template v-slot:item.fup="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'fup')">{{ item.fup }}</span>
        </template>
        <template v-slot:item.converting="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'converting')"
            :title="`Verify count: ${item.converting}`">{{ item.converting }}</span>
        </template>
        <template v-slot:item.converted="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'converted')">{{ item.converted }}</span>
        </template>
        <template v-slot:item.closed="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'closed')">{{ item.closed }}</span>
        </template>
        <template v-slot:item.wtr="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'wtr')">{{ item.wtr }}</span>
        </template>
        <template v-slot:item.wts="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'wts')">{{ item.wts }}</span>
        </template>
        <template v-slot:item.WTLS="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'WTLS')">{{ item.WTLS }}</span>
        </template>
        <template v-slot:item.wtb="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'wtb')">{{ item.wtb }}</span>
        </template>
        
        <template v-slot:item.not_interested="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'not_interested')">{{ item.not_interested }}</span>
        </template>
        <template v-slot:item.future="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'future')">{{ item.future }}</span>
        </template>
        <template v-slot:item.future3="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'future3')">{{ item.future3 }}</span>
        </template>
        <template v-slot:item.others="{ item }">
          <span class="clickable-number" @click.prevent="showRowDetailedRecords(item, 'others')">{{ item.others }}</span>
        </template>
      </v-data-table>
    </div>
    <crud-dialog v-model="dialog" :dialog-title="dialogTitle" :detailed-records="detailedRecords"
      @update-records="updateRecords" />

      <v-dialog v-model="wantToDialog" max-width="600px">
        <v-card>
          <v-card-title class="headline">Want To Records (Ratings 8-10)</v-card-title>
          <v-card-text>
            <div v-for="(record, index) in wantToRecords" :key="index" class="want-to-record">
              <pre>{{ formatWantToInfo(record) }}</pre>
            </div>
          </v-card-text>
          <v-card-actions>
            <v-btn color="primary" @click="wantToDialog = false">Close</v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>
  </div>
</template>

<script setup>
import { gql } from '@apollo/client/core';
import client from '../apollo-client';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { ref, computed, watch, onMounted } from 'vue';
import { PhoneIdStore } from '../stores/user';
import { loadByProjectFunc, updateContact, formatDateForStrapi } from '../utils/vgraphql';
import CrudDialog from './CrudDialog.vue';

// Reactive state
const defaultPhoneStore = PhoneIdStore();
const dialStats = ref({});
const loading = ref(true);
const error = ref(null);
const selectedYear = ref('-');
const selectedMonth = ref('');
const selectedDay = ref('');
const selectedCompany = ref('');
const selectedPhoneId = ref('');
const showAssignee = ref(false);
const dialogTitle = ref('');
const detailedRecords = ref([]);
const dialog = ref(false);
const rawLeads = ref([]);
const showDefaultPhoneIdDialog = ref(false);
const lastColumnClicked = ref(null);
const isHeaderClick = ref(false);
const selectedProject = ref(localStorage.getItem('selectedProject') || '');
const wantToDialog = ref(false);
const wantToRecords = ref([]);

// Static data
const months = [
  { value: '01', label: 'January' },
  { value: '02', label: 'February' },
  { value: '03', label: 'March' },
  { value: '04', label: 'April' },
  { value: '05', label: 'May' },
  { value: '06', label: 'June' },
  { value: '07', label: 'July' },
  { value: '08', label: 'August' },
  { value: '09', label: 'September' },
  { value: '10', label: 'October' },
  { value: '11', label: 'November' },
  { value: '12', label: 'December' }
];

const projects = [
  'BUKIT OUG CONDOMINIUM', 'm_terra', 'Parklane 1', 'Parklane 2',
  'Parklane 3', 'Parklane 4', 'Parklane 5', 'Sutra Embun', 'rbj',
  'RSKU Sungai Long', 'Parklane OUG', 'task', 'TMN YARL',
  'trr1082044 Eco Majestic Semenyih', 'trr1082289 Union Heights ( Eco Sky )'
];

const companies = ['TRR', 'TITAN', 'EUM'];
const phoneIds = ['Alyssa H', 'Ashton H', 'Alvin H', 'Alvin S'];

// Computed properties
const years = computed(() => [
  { value: '-', text: '-' },
  ...Array.from({ length: 5 }, (_, i) => {
    const year = new Date().getFullYear() - i;
    return { value: year, text: year.toString() };
  })
]);


const showWantToRecords = () => {
  wantToRecords.value = rawLeads.value
    .filter(lead => {
      const rating = parseInt(lead.rating) || 0;
      return [8, 9, 10].includes(rating);
    })
    .map(lead => ({
      info: lead.info || 'No information available',  // Assuming 'info' is the field name
      name: lead.name || 'N/A',
      rating: lead.rating || 'N/A'
    }));
  wantToDialog.value = true;
};

const formatWantToInfo = (record) => {
  // Split the info string into lines and add emojis
  const infoLines = record.info.split('\n').filter(line => line.trim());
  const formattedLines = infoLines.map((line, index) => {
    const emojis = [
      '🏷️', '🏠', '📍', '📐', '📦', 
      '🚗', '🔑', '📅', '💸', '📌'
    ];
    const emoji = emojis[index] || '➡️';
    return `${emoji} ${line.trim()}`;
  });
  
  // Add name and rating at the top
  return `🏷️ Owner Name: ${record.name}
${formattedLines.join('\n')}`;
};
const days = computed(() => {
  if (!selectedMonth.value || selectedYear.value === '-') return [];
  const daysInMonth = new Date(
    parseInt(selectedYear.value),
    parseInt(selectedMonth.value),
    0
  ).getDate();
  return Array.from({ length: daysInMonth }, (_, i) => ({
    value: String(i + 1).padStart(2, '0'),
    text: String(i + 1)
  }));
});

const headers = computed(() => [
  { title: 'Date', value: 'date', sortable: false, width: '100px' },
  { title: 'Project', value: 'project', width: '150px' },
  ...(showAssignee.value ? [{ title: 'Assignee', value: 'assignee', width: '120px' }] : []),
  { title: '∑ Records', value: 'totalRecords', width: '80px' },
  { title: '∑ Backlog', value: 'backlog', width: '80px' },
  { title: '∑ Dials', value: 'totalDials', width: '40px' },
  { title: '∑ Rated Undialed', value: 'rated_undialed', width: '100px' },
  { title: '1:Failed', value: 'failed', width: '70px' },
  { title: '2:WhatsApp Send', value: 'whatsapp_send', width: '100px' },
  { title: '4:FUP', value: 'fup', width: '70px' },
  { title: '5:Responded', value: 'converting', width: '90px' },
  { title: '6:Interested', value: 'converted', width: '90px' },
  { title: '7:Closing', value: 'closed', width: '70px' },
  { title: '8:WTR', value: 'wtr', width: '70px' },
  { title: '9:WTS', value: 'wts', width: '70px' },
  { title: '10:WTLS', value: 'WTLS', width: '70px' },
  { title: '11:WTB', value: 'wtb', width: '70px' },
  { title: '12:Future', value: 'future', width: '70px' },
  { title: '12:Future 3+', value: 'future3', width: '70px' },
  { title: '12:Others', value: 'others', width: '70px' },
  { title: '20:Not Interested', value: 'not_interested', width: '100px' },
]);

// Derived values
const totalDials = computed(() => rawLeads.value.filter(lead => lead.dialedDate).length);
const totalBacklog = computed(() => rawLeads.value.filter(lead => !lead.dialedDate).length);
const totalRecordsFetch = computed(() => dialStats.value.totalRecordsFetched || 0);
const totalRecords = computed(() => rawLeads.value.length);

const tableItems = computed(() => {  //rating change
  return Object.entries(dialStats.value).flatMap(([date, projects]) =>
    Object.entries(projects).map(([project, entry]) => ({
      date: date === 'null' ? null : new Date(date).toISOString().split('T')[0],
      project,
      assignee: showAssignee.value ? entry.assignee : undefined,
      totalDials: entry.totalDials || 0,
      backlog: entry.backlog || 0,
      rated_undialed: entry.rated_undialed || 0,
      totalRecords: entry.totalRecords || 0,
      failed: entry.failed || 0,
      whatsapp_send: entry.whatsapp_send || 0,
      fup: entry.fup || 0,
      converting: entry.converting || 0,
      converted: entry.converted || 0,
      closed: entry.closed || 0,
      wtr: entry.wtr || 0,
      wts: entry.wts || 0,
      WTLS: entry.WTLS || 0,
      wtb: entry.wtb || 0,
      not_interested: entry.not_interested || 0,
      future: entry.future || 0,
      future3: entry.future3 || 0,
      others: entry.others || 0,
      rating: entry.rating
    }))
  ).sort((a, b) => (a.date || '').localeCompare(b.date || ''));
});

// Methods
const fetchDialingData = async () => {
  loading.value = true;
  error.value = null;
  try {
    const { data } = await client.query({
      query: gql`
        query GetDials($filters: LeadFiltersInput) {
          leads(
            pagination: { limit: 2000 }
            sort: ["project", "dialedDate"]
            filters: $filters
          ) {
            data {
              id
              attributes {
                requestType
                dialedDate
                lastCall
                interaction
                assignee
                project
                phoneNumber
                name
                company
                rating
                status
                phoneId
                updatedAt
              }
            }
            meta {
              pagination {
                total
              }
            }
          }
        }
      `,
      variables: { filters: getFilters() }
    });
    processLeadsData(data);
  } catch (err) {
    error.value = `Failed to load data: ${err.message}`;
  } finally {
    loading.value = false;
  }
};

const getFilters = () => {
  const filters = {};
  if (selectedYear.value !== '-') {
    let startDate, endDate;
    if (selectedDay.value) {
      startDate = `${selectedYear.value}-${selectedMonth.value}-${selectedDay.value}`;
      endDate = startDate;
    } else if (selectedMonth.value) {
      startDate = `${selectedYear.value}-${selectedMonth.value}-01`;
      const lastDay = new Date(
        parseInt(selectedYear.value),
        parseInt(selectedMonth.value),
        0
      ).getDate();
      endDate = `${selectedYear.value}-${selectedMonth.value}-${lastDay}`;
    } else {
      startDate = `${selectedYear.value}-01-01`;
      endDate = `${selectedYear.value}-12-31`;
    }
    filters.dialedDate = {
      gte: formatDateForStrapi(startDate),
      lte: formatDateForStrapi(endDate)
    };
  }
  
  if (selectedProject.value && selectedProject.value !== '') {
    if (selectedProject.value === 'All > 0') {
      filters.rating = { gt: 0 };
    } else if (selectedProject.value === 'All > 3 < 11') {
      filters.rating = { gt: 3, lt: 11 };
    } else {
      filters.project = { eq: selectedProject.value };
    }
  }
  
  if (selectedCompany.value && selectedCompany.value !== '') {
    filters.company = { eq: selectedCompany.value };
  }
  if (selectedPhoneId.value) {
    if (selectedPhoneId.value === 'blank') {
      filters.phoneId = { in: [null, ''] };
    } else if (selectedPhoneId.value !== '') {
      filters.phoneId = { eq: selectedPhoneId.value };
    }
  }
  return filters;
};

const processLeadsData = (data) => {
  rawLeads.value = data.leads.data.map(lead => ({
    id: lead.id,
    ...lead.attributes,
    dialedDate: lead.attributes.dialedDate ? new Date(lead.attributes.dialedDate).toISOString().split('T')[0] : null,
    updatedAt: lead.attributes.updatedAt ? new Date(lead.attributes.updatedAt).toISOString().split('T')[0] : null,
    lastCall: lead.attributes.lastCall ? new Date(lead.attributes.lastCall).toISOString().split('T')[0] : null
  }));

  let filteredLeads = rawLeads.value;
  if (selectedProject.value === 'All > 0') {
    filteredLeads = rawLeads.value.filter(lead => parseInt(lead.rating) > 0);
  } else if (selectedProject.value === 'All > 3 < 11') {
    filteredLeads = rawLeads.value.filter(lead => {
      const rating = parseInt(lead.rating) || 0;
      return rating > 3 && rating < 11;
    });
  }

  dialStats.value = filteredLeads.reduce((acc, lead) => {
    const { rating, dialedDate, project, company, assignee, phoneId, lastCall, updatedAt } = lead;
    const dateKey = dialedDate || 'null';
    const projectKey = project || 'Unknown';
    const ratingValue = parseInt(rating) || 0;
    acc[dateKey] = acc[dateKey] || {};
    acc[dateKey][projectKey] = acc[dateKey][projectKey] || createProjectEntry(company, assignee);
    const isBlankPhoneId = selectedPhoneId.value === 'blank' && (phoneId === null || phoneId === '');
    const isMatchingPhoneId = selectedPhoneId.value === '' || phoneId === selectedPhoneId.value || isBlankPhoneId;
    if (isMatchingPhoneId) {
      updateStats(acc[dateKey][projectKey], ratingValue, dialedDate, lastCall, updatedAt);
    }
    return acc;
  }, {});
};

const createProjectEntry = (company, assignee) => ({
  assignee: assignee || 'N/A',
  company: company || 'Unknown',
  totalDials: 0,
  backlog: 0,
  rated_undialed: 0,
  failed: 0,
  whatsapp_send: 0,
  fup: 0,
  converting: 0,
  converted: 0,
  closed: 0,
  wtr: 0,
  wts: 0,
  WTLS: 0,
  wtb: 0,
  not_interested: 0,
  future: 0,
  future3: 0,
  others: 0,
  rating: 0
});

const updateStats = (entry, rating, dialedDate, lastCall, updatedAt) => {
  const parsedRating = parseInt(rating) || 0;
  entry.totalRecords = (entry.totalRecords || 0) + 1;
  if (dialedDate) {
    entry.totalDials = (entry.totalDials || 0) + 1;
  }
  
  const threeMonthsFromNow = new Date();
  threeMonthsFromNow.setMonth(threeMonthsFromNow.getMonth() + 3);
  
  const referenceDate = lastCall ? new Date(lastCall) :
                       dialedDate ? new Date(dialedDate) :
                       updatedAt ? new Date(updatedAt) : null;

  switch (parsedRating) {
    case 1: entry.failed++; break;
    case 2: entry.whatsapp_send++; break;
    case 4: entry.fup++; break;
    case 5: entry.converting++; break;
    case 6: entry.converted++; break;
    case 7: entry.closed++; break;
    case 8: entry.wtr++; break;
    case 9: entry.wts++; break;
    case 10: entry.WTLS++; break;
    case 11: entry.wtb++; break;
    case 20: entry.not_interested++; break;
    case 12:
      if (referenceDate && referenceDate > threeMonthsFromNow) {
        entry.future3 = (entry.future3 || 0) + 1;
      } else {
        entry.future++;
      }
      break;
    default:
      if (parsedRating > 11) entry.others++;
      break;
  }
  if (!dialedDate && (parsedRating === 0 || rating === null)) {
    entry.backlog = (entry.backlog || 0) + 1;
  }
  if (!dialedDate && parsedRating > 0) {
    entry.rated_undialed = (entry.rated_undialed || 0) + 1;
  }
};

const showDetailedRecords = (column) => {
  isHeaderClick.value = true;
  lastColumnClicked.value = column;
  dialogTitle.value = column.charAt(0).toUpperCase() + column.slice(1);
  const ratingFilter = getRatingFilter(column);
  detailedRecords.value = rawLeads.value
    .filter(lead => {
      const rating = parseInt(lead.rating) || 0;
      const dialedDate = lead.dialedDate ? new Date(lead.dialedDate).toISOString().split('T')[0] : null;
      const isBlankPhoneId = selectedPhoneId.value === 'blank' && (lead.phoneId === null || lead.phoneId === '');
      const matchesPhoneId = selectedPhoneId.value === '' || lead.phoneId === selectedPhoneId.value || isBlankPhoneId;
      const matchesFilters = (
        ratingFilter(rating, dialedDate, lead.lastCall, lead.updatedAt) &&
        (selectedProject.value === '' || selectedProject.value === 'All > 0' || selectedProject.value === 'All > 3 < 11' || lead.project === selectedProject.value) &&
        (selectedCompany.value === '' || lead.company === selectedCompany.value) &&
        matchesPhoneId
      );
      return matchesFilters;
    })
    .map(formatLeadDetails);
  dialog.value = true;
};

const showRowDetailedRecords = (item, column) => {
  isHeaderClick.value = false;
  const expectedCount = item[column];
  const dateFilter = item.date ? item.date : null;
  const ratingFilter = getRatingFilter(column);
  const filtered = rawLeads.value.filter(lead => {
    const leadDate = lead.dialedDate ? lead.dialedDate.split('T')[0] : null;
    const rating = parseInt(lead.rating) || 0;
    const isBlankPhoneId = selectedPhoneId.value === 'blank' && (lead.phoneId === null || lead.phoneId === '');
    const matchesPhoneId = selectedPhoneId.value === '' || lead.phoneId === selectedPhoneId.value || isBlankPhoneId;
    return (
      (dateFilter === null ? leadDate === null : leadDate === dateFilter) &&
      lead.project === item.project &&
      matchesPhoneId &&
      ratingFilter(rating, lead.dialedDate, lead.lastCall, lead.updatedAt)
    );
  });
  detailedRecords.value = filtered.map(formatLeadDetails);
  dialogTitle.value = `${column} (${filtered.length}/${expectedCount} records) - ${item.date || 'N/A'} ${item.project}`;
  dialog.value = true;
};

const getRatingFilter = (column) => {  //rating change
  return {
    totalRecords: () => true,
    totalDials: (r, dialedDate) => !!dialedDate,
    backlog: (r, dialedDate) => !dialedDate && (r === 0 || r === null),
    rated_undialed: (r, dialedDate) => !dialedDate && r > 0,
    failed: (r) => r === 1,
    whatsapp_send: (r) => r === 2,
    fup: (r) => r === 4,
    converting: (r) => r === 5,
    converted: (r) => r === 6,
    closed: (r) => r === 7,
    wtr: (r) => r === 8,
    wts: (r) => r === 9,
    WTLS: (r) => r === 10,
    wtb: (r) => r === 11,
    not_interested: (r) => r === 20,
    future: (r) => r === 12,
    future3: (r, dialedDate, lastCall, updatedAt) => {
      if (r !== 11) return false;
      const threeMonthsFromNow = new Date();
      threeMonthsFromNow.setMonth(threeMonthsFromNow.getMonth() + 3);
      const referenceDate = lastCall ? new Date(lastCall) :
                          dialedDate ? new Date(dialedDate) :
                          updatedAt ? new Date(updatedAt) : null;
      return referenceDate && referenceDate > threeMonthsFromNow;
    },
    others: (r) => r > 11
  }[column] || (() => false);
};

const formatLeadDetails = (lead) => ({
  id: lead.id,
  dialedDate: lead.dialedDate?.split('T')[0] || 'N/A',
  updatedAt: lead.updatedAt?.split('T')[0] || 'N/A',
  lastCall: lead.lastCall?.split('T')[0] || 'N/A',
  project: lead.project || 'Unknown',
  name: lead.name,
  assignee: lead.assignee || 'N/A',
  phoneNumber: lead.phoneNumber,
  phoneId: lead.phoneId || 'N/A',
  status: lead.status,
  interaction: lead.interaction || '',
  rating: lead.rating || 0,
  requestType: lead.requestType || 'N/A'
});

const calculateTotal = (column, items) => {
  if (column === 'date') {
    return items.filter(item => item.date).length; // Count non-null dates
  } else if (column === 'project') {
    return items.length; // Total number of rows (projects)
  } else if (column === 'assignee') {
    return items.filter(item => item.assignee && item.assignee !== 'N/A').length; // Count non-empty assignees
  } else {
    return items.reduce((total, item) => {
      const value = item[column] || 0;
      return total + (typeof value === 'number' ? value : 0);
    }, 0);
  }
};

const getHeaderClass = (column) => {
  const headerClasses = {
    totalRecords: 'colored-header',
    backlog: 'colored-header',
    totalDials: 'colored-header',
    rated_undialed: 'colored-header',
    failed: 'colored-header4',
    whatsapp_send: 'colored-header3',
    fup: 'colored-header3',
    converting: 'colored-header3',
    converted: 'colored-header3',
    closed: 'colored-header3',
    wtr: 'colored-header5',
    wts: 'colored-header5',
    WTLS: 'colored-header5',
    wtb: 'colored-header5',
    future: 'colored-header2',
    future3: 'colored-header2',
    others: 'colored-header2',
    not_interested: 'colored-header2'
  };
  return headerClasses[column] || '';
};

const updateRecords = async (newRecords, record) => {
  detailedRecords.value = newRecords;
  if (record?.id) {
    const updatedRecord = await updateContact(record);
    if (updatedRecord) {
      const index = detailedRecords.value.findIndex(r => r.id === record.id);
      if (index !== -1) {
        detailedRecords.value[index] = { ...detailedRecords.value[index], ...updatedRecord };
        const rawIndex = rawLeads.value.findIndex(r => r.id === record.id);
        if (rawIndex !== -1) {
          rawLeads.value[rawIndex] = { ...rawLeads.value[rawIndex], ...updatedRecord };
       //   fetchDialingData();
        }
      }
              fetchDialingData();
    }
  }
};

const printPDF = () => {
  const doc = new jsPDF();
  doc.autoTable({
    head: [headers.value.map(h => h.title)],
    body: tableItems.value.map(item => headers.value.map(h => item[h.value] || '')),
  });
  doc.save('dialing_data.pdf');
};

const handleDefaultPhoneIdChange = (value) => {
  defaultPhoneStore.defaultPhoneId = value;
};

const saveDefaultPhoneId = () => {
  showDefaultPhoneIdDialog.value = false;
  fetchDialingData();
};

// Watchers
watch(
  [
    selectedYear, 
    selectedMonth, 
    selectedDay, 
    selectedProject, 
    selectedCompany, 
    selectedPhoneId,
    showAssignee
  ], 
  ([year, month, day, project, company, phoneId, assigneeFlag]) => {
    localStorage.setItem('selectedYear', year);
    localStorage.setItem('selectedMonth', month);
    localStorage.setItem('selectedDay', day);
    localStorage.setItem('selectedProject', project);
    localStorage.setItem('selectedCompany', company);
    localStorage.setItem('selectedPhoneId', phoneId);
    localStorage.setItem('showAssignee', assigneeFlag.toString());
    
    fetchDialingData();
  }
);

watch(dialog, (newVal, oldVal) => {
  if (newVal && !oldVal && isHeaderClick.value && lastColumnClicked.value) {
    fetchDialingData().then(() => {
      showDetailedRecords(lastColumnClicked.value);
    });
  }
});

// Lifecycle hooks
onMounted(() => {
  if (!defaultPhoneStore.defaultPhoneId || defaultPhoneStore.defaultPhoneId === '') {
    showDefaultPhoneIdDialog.value = true;
  } else {
    fetchDialingData();
  }
});
</script>

