<template>
  <dialog :open="open" class="view-dialog">
    <div class="dialog-content">
      <h2>View Note</h2>
      <div class="form-group">
        <label>Language:</label>
        <input :value="safeNote.language" readonly />
      </div>

      <div class="form-group">
        <label>Title:</label>
        <input :value="safeNote.title" readonly />
      </div>
   
      <div class="dialog-buttons">
        <button @click="close" class="btn-close">Close</button>
      </div>
      <div class="form-group">
        <label>Content:</label>
        <div v-html="safeNote.content" class="content-display"></div>
      </div>
    </div>
  </dialog>
</template>

<script>
export default {
  props: {
    open: {
      type: Boolean,
      required: true
    },
    note: {
      type: Object,
      default: () => null
    }
  },
  computed: {
    safeNote() {
      return this.note || {
        title: 'No title available',
        content: 'No content available',
        language: 'unknown'  // Changed property
      };
    }
  },
  methods: {
    close() {
      this.$emit('close');
    }
  }
};
</script>

<style scoped>
.view-dialog {
  width: 80%;
  max-width: 800px;
  max-height: 90vh;
  overflow-y: auto;
  border: none;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.3);
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1000;
  margin: 0;
}

.dialog-content {
  padding: 20px 30px;
  background: white;
}

.form-group {
  margin-bottom: 15px;
  padding: 0 15px;
}

.form-group label {
  display: block;
  margin-bottom: 5px;
}

.form-group input {
  width: 100%;
  padding: 8px;
  background: #f5f5f5;
  border: 1px solid #ddd;
}

.content-display {
  border: 1px solid #ddd;
  padding: 15px;
  min-height: 100px;
  overflow: auto;
  margin: 0 15px;
}

.dialog-buttons {
  margin-top: 20px;
  text-align: right;
  padding: 0 15px;
}
</style>